-- Table structure for ld_activity
-- ----------------------------
DROP TABLE IF EXISTS `ld_activity`;
CREATE TABLE `ld_activity` (
  `activityid` int(19) NOT NULL DEFAULT '0',
  `subject` varchar(100) NOT NULL,
  `semodule` varchar(20) DEFAULT NULL,
  `activitytype` varchar(200) NOT NULL,
  `date_start` datetime NOT NULL,
  `due_date` datetime DEFAULT NULL,
  `sendnotification` varchar(3) NOT NULL DEFAULT '0',
  `duration_hours` varchar(200) DEFAULT NULL,
  `duration_minutes` varchar(200) DEFAULT NULL,
  `status` varchar(200) DEFAULT NULL,
  `eventstatus` varchar(200) DEFAULT NULL,
  `priority` varchar(200) DEFAULT NULL,
  `location` varchar(150) DEFAULT NULL,
  `notime` varchar(3) NOT NULL DEFAULT '0',
  `visibility` varchar(50) NOT NULL DEFAULT '公共',
  `recurringtype` varchar(200) DEFAULT NULL,
  `accountid` int(19) DEFAULT NULL,
  `contactid` int(19) DEFAULT NULL,
  `potentialid` int(19) DEFAULT NULL,
  `approvestatus` varchar(200) DEFAULT '未提交',
  `approveby` int(1) DEFAULT NULL,
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `description` text,
  `deleted` int(11) DEFAULT '0',
  `product_id` int(19) DEFAULT '0',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `to_email` text,
  `cc_email` text,
  `print_times` int(11) DEFAULT '0',
  `approvetime` datetime DEFAULT NULL,
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `team_memberid` text,
  `tag` varchar(50) DEFAULT NULL,
  `latestpushtime` datetime DEFAULT NULL,
  `bgcolor` varchar(100) DEFAULT NULL,
  `currency_id` int(4) DEFAULT '1',
  `conversion_rate` decimal(12,6) DEFAULT NULL,
  `currency_symbol` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`activityid`),
  KEY `activity_activityid_subject_idx` (`activityid`,`subject`) USING BTREE,
  KEY `activity_activitytype_date_start_idx` (`activitytype`,`date_start`) USING BTREE,
  KEY `activity_date_start_due_date_idx` (`date_start`,`due_date`) USING BTREE,
  KEY `activity_date_start_time_start_idx` (`date_start`) USING BTREE,
  KEY `activity_eventstatus_idx` (`eventstatus`) USING BTREE,
  KEY `activity_status_idx` (`status`) USING BTREE,
  KEY `activity_deleted` (`deleted`) USING BTREE,
  CONSTRAINT `ld_activity_ibfk_1` FOREIGN KEY (`activityid`) REFERENCES `ld_crmentity` (`crmid`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

