CREATE TABLE `ld_customtable_sorting` (
  `report_id` int(19) NOT NULL COMMENT '报表ID',
  `sorttype` varchar(20) DEFAULT NULL COMMENT '排序方式 可选“按报表列名(bycolumnname)”、“按分组统计结果值（byresult）”，默认“按报表列名” ',
  `columnmodule` varchar(50) DEFAULT NULL COMMENT '排序字段来自模块 ',
  `columns` varchar(255) DEFAULT NULL COMMENT '排序字段',
