-- ----------------------------
-- Table structure for ld_questionnaire
-- ----------------------------
DROP TABLE IF EXISTS `ld_questionnaire`;
CREATE TABLE `ld_questionnaire` (
  `questionnaireid` int(11) NOT NULL AUTO_INCREMENT,
  `questionnaire_no` varchar(100) NOT NULL COMMENT '编号',
  `name` varchar(255) DEFAULT NULL COMMENT '问卷名称',
  `description` text COMMENT '问卷描述',
  `status` varchar(50) DEFAULT '暂停' COMMENT '暂停、正在回收',
  `recoverys` int(11) DEFAULT NULL COMMENT '回收量',
  `views` int(11) DEFAULT NULL COMMENT '浏览量',
  `createdtime` datetime DEFAULT NULL COMMENT '创建时间',
  `modifiedtime` datetime DEFAULT NULL COMMENT '更新时间',
  `smownerid` int(11) DEFAULT NULL COMMENT '负责人',
  `smcreatorid` int(11) DEFAULT NULL COMMENT '创建人',
  `modifiedby` int(11) DEFAULT NULL COMMENT '最新更新人',
  `deleted` int(11) DEFAULT '0',
  `recovery_endtime` datetime DEFAULT NULL COMMENT '回收截止时间',
  `recovery_endremarks` text COMMENT '问卷结束语(html)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `category` varchar(50) DEFAULT '外部',
  `tag` varchar(50) DEFAULT NULL,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(200) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `latestpushtime` datetime DEFAULT NULL,
  `team_memberid` text,
  `accountid` int(19) DEFAULT '0',
  PRIMARY KEY (`questionnaireid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

