-- ----------------------------
-- Table structure for ld_wx_checkin
-- ----------------------------
DROP TABLE IF EXISTS `ld_wx_checkin`;
CREATE TABLE `ld_wx_checkin` (
  `id` int(19) NOT NULL AUTO_INCREMENT COMMENT '企业微信打卡表主键',
  `userid` varchar(255) DEFAULT NULL COMMENT '微信成员ID',
  `groupname` varchar(255) DEFAULT NULL COMMENT '打卡规则名称',
  `checkin_type` varchar(255) DEFAULT NULL COMMENT '打卡类型，包含上班打卡，下班打卡，外出打卡',
  `exception_type` varchar(255) DEFAULT NULL COMMENT '异常类型,包含时间异常，地点异常，未打卡，wifi异常，非常用设备。如果有多个异常，以分号间隔',
  `checkin_time` int(11) DEFAULT NULL COMMENT '打卡时间',
  `checkin_time_date` datetime DEFAULT NULL COMMENT '格式化的打卡时间',
  `location_title` varchar(255) DEFAULT NULL COMMENT '打卡地点title',
  `location_detail` text COMMENT '打卡地点详情',
  `wifiname` varchar(255) DEFAULT NULL COMMENT '打卡wifi名称',
  `notes` text COMMENT '打卡备注',
  `wifimac` varchar(255) DEFAULT NULL COMMENT '打卡的MAC地址/bssid',
  `mediaids` varchar(255) DEFAULT NULL COMMENT '打卡的附件media_id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Table structure for ld_wx_checkin_dingtalk
-- ----------------------------
DROP TABLE IF EXISTS `ld_wx_checkin_dingtalk`;
CREATE TABLE `ld_wx_checkin_dingtalk` (
  `id` bigint(20) NOT NULL COMMENT '钉钉打卡唯一标识ID',
  `userid` varchar(255) DEFAULT NULL COMMENT '钉钉用户ID',
  `groupid` bigint(20) DEFAULT NULL COMMENT '考勤组ID',
  `planid` bigint(20) DEFAULT NULL COMMENT '排班ID',
  `recordid` bigint(20) DEFAULT NULL COMMENT '打卡记录ID',
  `checktype` varchar(255) DEFAULT NULL COMMENT '考勤类型,OnDuty：上班 OffDuty：下班',
  `timeresult` varchar(255) DEFAULT NULL COMMENT '时间结果 Normal：正常;Early：早退;Late：迟到;SeriousLate：严重迟到；Absenteeism：旷工迟到；NotSigned：未打卡',
  `workdate_date` datetime DEFAULT NULL COMMENT '格式化工作日',
  `basechecktime_date` datetime DEFAULT NULL COMMENT '格式化计算迟到和早退，基准时间',
  `userchecktime_date` datetime DEFAULT NULL COMMENT '格式化实际打卡时间,  用户打卡时间的毫秒数',
  `workdate` bigint(20) DEFAULT NULL COMMENT '工作日',
  `basechecktime` bigint(20) DEFAULT NULL COMMENT '计算迟到和早退，基准时间',
  `userchecktime` bigint(20) DEFAULT NULL COMMENT '实际打卡时间,  用户打卡时间的毫秒数',
  `locationresult` varchar(255) DEFAULT NULL COMMENT '位置结果 Normal：范围内；Outside：范围外；NotSigned：未打卡',
  `approveid` bigint(20) DEFAULT NULL COMMENT '关联的审批id，当该字段非空时，表示打卡记录与请假、加班等审批有关',
  `procinstid` bigint(20) DEFAULT NULL COMMENT '关联的审批实例id，当该字段非空时，表示打卡记录与请假、加班等审批有关。可以与获取单个审批数据配合使用',
  `sourceType` varchar(255) DEFAULT NULL COMMENT '数据来源',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Table structure for ld_wx_checkin_reissue
-- ----------------------------
DROP TABLE IF EXISTS `ld_wx_checkin_reissue`;
CREATE TABLE `ld_wx_checkin_reissue` (
  `id` int(19) NOT NULL AUTO_INCREMENT COMMENT '企业微信补卡表主键',
  `sp_num` varchar(255) DEFAULT NULL COMMENT '审批单号',
  `userid` varchar(255) DEFAULT NULL COMMENT '微信成员ID',
  `sp_status` varchar(255) DEFAULT NULL COMMENT '审批状态：1审批中；2 已通过；3已驳回；4已取消；6通过后撤销；10已支付',
  `checkin_time` int(11) DEFAULT NULL COMMENT '补卡时间',
  `checkin_time_date` datetime DEFAULT NULL COMMENT '格式化的补卡时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

