        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'zh',@labelbol,'秒',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'zh' AND labelbol=@labelbol AND Labeltype=@labeltype);
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'en',@labelbol,'Second',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'en' AND labelbol=@labelbol AND Labeltype=@labeltype);

        SET @labelbol = 'NewCarousel';
        SET @labeltype = 'jspop';
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'zh',@labelbol,'新增轮播图',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'zh' AND labelbol=@labelbol AND Labeltype=@labeltype);
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'en',@labelbol,'New Carousel',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'en' AND labelbol=@labelbol AND Labeltype=@labeltype);

        SET @labelbol = 'CarouselTitle';
        SET @labeltype = 'jspop';
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'zh',@labelbol,'轮播图标题',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'zh' AND labelbol=@labelbol AND Labeltype=@labeltype);
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'en',@labelbol,'Carousel Title',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'en' AND labelbol=@labelbol AND Labeltype=@labeltype);

        SET @labelbol = 'CarouselLink';
        SET @labeltype = 'jspop';
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'zh',@labelbol,'轮播图超链接',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'zh' AND labelbol=@labelbol AND Labeltype=@labeltype);
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'en',@labelbol,'Carousel Link',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'en' AND labelbol=@labelbol AND Labeltype=@labeltype);

        SET @labelbol = 'AddCarousel';
        SET @labeltype = 'jspop';
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'zh',@labelbol,'+ 新增轮播图',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'zh' AND labelbol=@labelbol AND Labeltype=@labeltype);
        INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
        SELECT 'en',@labelbol,'+ Add Carousel',@labeltype FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'en' AND labelbol=@labelbol AND Labeltype=@labeltype);
    END IF;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for addtabintoprofile
-- ----------------------------
DROP PROCEDURE IF EXISTS `addtabintoprofile`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `addtabintoprofile`(
    tabname varchar(50),
    permissions int(19)
)
begin
	declare done  int  default 0;
	declare pprofileid  int ;
	declare cur1 CURSOR FOR SELECT profileid  FROM  ld_profile;
declare continue handler  for not   found  SET done =1;
	set @sql =concat('select tabid into @tabid from ld_tab where name=','''',tabname,'''');
prepare stmt from @sql;
execute stmt;
deallocate  prepare stmt;
OPEN cur1;
Fetch cur1 into pprofileid;
loop1: while  done<>1 DO
	set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',0,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=0)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',1,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=1)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',2,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=2)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',3,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=3)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',4,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=4)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',11,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=11)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
Fetch cur1 into pprofileid;
end while loop1;
close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for addtablefilecolumn
-- ----------------------------
DROP PROCEDURE IF EXISTS `addtablefilecolumn`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `addtablefilecolumn`()
BEGIN
	DECLARE done INT DEFAULT 0 ;
	DECLARE ccolumnname VARCHAR (100) ;
    DECLARE ttablename VARCHAR (100) ;
    DECLARE cur2 CURSOR FOR
        SELECT columnname,tablename FROM ld_tabdetailfield
            WHERE (bigtype = 'fileattachment' OR bigtype = 'image') AND savedatabase = 'yes';
DECLARE CONTINUE HANDLER FOR NOT found SET done = 1 ;
OPEN cur2 ;
FETCH cur2 INTO ccolumnname,ttablename ;
loop2: WHILE done <> 1
			  	DO SET @SQL = Concat(' call AddColumn( "',ttablename,'","',ccolumnname,'","char","5","")') ;
        PREPARE stmt FROM @SQL ;
        EXECUTE stmt ;
        DEALLOCATE PREPARE stmt ;
        FETCH cur2 INTO ccolumnname,ttablename ;
        END
WHILE loop2 ;
CLOSE cur2 ;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for addtableIndex
-- ----------------------------
DROP PROCEDURE IF EXISTS `addtableIndex`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `addtableIndex`(
	tablename 	varchar(50),
	indexname 	varchar(50),
	columnlist 	varchar(50)
)
BEGIN
	
	SELECT DATABASE() into @datebase;

	SET @sql2=CONCAT('select count(*) into @cnt from information_schema.statistics where table_name=''',tablename,''' and index_name=''',indexname,'''  and table_schema=''',@datebase,'''');  
	PREPARE statement_name FROM @sql2;  
	EXECUTE statement_name; 
	DEALLOCATE PREPARE statement_name;

	IF @cnt=0 THEN 
		SET @sql3=CONCAT('alter  table ',tablename,' add  index ',indexname,' (',columnlist,')' );
		PREPARE statement_name FROM @sql3;  
		EXECUTE statement_name; 
		DEALLOCATE PREPARE statement_name;
  END IF;
	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for add_shouye_jianbao
-- ----------------------------
DROP PROCEDURE IF EXISTS `add_shouye_jianbao`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `add_shouye_jianbao`(
	tmp_module VARCHAR(100),
	tmp_label  VARCHAR(100),
	tmp_zhname VARCHAR(100),
	tmp_enname VARCHAR(100),
	tmp_formulatype VARCHAR(100),
	tmp_formulacolumn VARCHAR(100),
	tmp_querydatefield VARCHAR(100)
)
BEGIN

	SET @jianbao_module=tmp_module;
	SET @jianbao_label=tmp_label;
	SET @jianbao_zhname=tmp_zhname;
	SET @jianbao_enname=tmp_zhname;
	SET @jianbao_formulatype=tmp_formulatype;
	SET @jianbao_formulacolumn=tmp_formulacolumn;	
	SET @querydatefield=tmp_querydatefield;

	IF tmp_formulatype='count' THEN 
		SET @jianbao_formulacolumn=(
			SELECT 
				CONCAT(b.tablename,'.',a.entityidfield)
			FROM ld_entityname a
			INNER JOIN ld_field b ON b.tabid=a.tabid AND b.columnname='smownerid'
			WHERE a.modulename=@jianbao_module
			LIMIT 1
		);

		SET @ico='crm_SalesOrder.png';
	ELSE
		SET @jianbao_formulacolumn=(
			SELECT 
				CONCAT(tablename,'.',@jianbao_formulacolumn) 
			FROM ld_field 
			WHERE columnname='smownerid' 
				AND tabid=(SELECT tabid FROM ld_tab WHERE name=tmp_module) 
			LIMIT 1
		);

		SET @ico='item-ico-salesorder';
	END IF;
	
	IF @jianbao_module IN ('Accounts','Leads') THEN
		SET @page_to=CONCAT('index.php?pageto_module=',@jianbao_module,'&pageto_action=index&pagepublicaccounttype=ALLACCOUNT');
	ELSE
		SET @page_to=CONCAT('index.php?pageto_module=',@jianbao_module,'&pageto_action=index');
	END IF;

	SET @seq=IFNULL((SELECT MAX(sequence) FROM ld_homestuffdetail),0)+1;

	IF NOT EXISTS (SELECT 1 FROM ld_homestuffdetail WHERE stufflabel=@jianbao_label) THEN
		INSERT INTO `ld_homestuffdetail` (`stuffid`, `stufflabel`, `stufflabeltype`, `compute_columns`, `compute_type`, `pageurl`, `sequence`, `cssname`, `presence`, `icon`)
		SELECT '35',@jianbao_label,'fixedstr',@jianbao_formulacolumn,@jianbao_formulatype,@page_to,@seq,'item-ico-salesorder','yes',@ico;

		DELETE FROM ld_desk WHERE labelbol=@jianbao_label AND Labeltype='fixedstr';
		INSERT INTO `ld_desk` (`languagetype`, `labelbol`, `fieldlabel`, `Labeltype`) 
		SELECT 'zh',@jianbao_label,@jianbao_zhname, 'fixedstr';

		INSERT INTO `ld_desk` (`languagetype`, `labelbol`, `fieldlabel`, `Labeltype`) 
		SELECT 'en',@jianbao_label,@jianbao_enname, 'fixedstr';


		SET @homestuffdetailid=(SELECT id FROM ld_homestuffdetail WHERE stufflabel=@jianbao_label LIMIT 1);

		SET @date_column=(
			SELECT
				CONCAT(a.tablename,':',a.columnname,':',a.columnname,':',c.name,'_',b.fieldlabel,':',LEFT(a.typeofdata,IF(LOCATE('~',a.typeofdata)-1>0,LOCATE('~',a.typeofdata)-1,1)))
			FROM ld_field a
			INNER JOIN ld_tranlabel b ON b.trantable='ld_field' AND b.Relateid=a.fieldid AND b.languagetype='zh'
			LEFT JOIN ld_tab c ON c.tabid=a.tabid
			WHERE c.name=@jianbao_module
				AND a.columnname=@querydatefield
			LIMIT 1	
		);

		SET @approve_column=(
			SELECT
				CONCAT(a.tablename,':',a.columnname,':',a.columnname,':',c.name,'_',b.fieldlabel,':',LEFT(a.typeofdata,IF(LOCATE('~',a.typeofdata)-1>0,LOCATE('~',a.typeofdata)-1,1)))
			FROM ld_field a
			INNER JOIN ld_tranlabel b ON b.trantable='ld_field' AND b.Relateid=a.fieldid AND b.languagetype='zh'
			LEFT JOIN ld_tab c ON c.tabid=a.tabid
			WHERE c.name=@jianbao_module
				AND a.columnname='approvestatus'
			LIMIT 1	
		);


		INSERT INTO `ld_homestuffdetailcondition` (`homestuffdetailid`, `groupid`, `columns`, `value`, `comparator`)
		SELECT @homestuffdetailid, '1', @date_column, '', '';

		INSERT INTO `ld_homestuffdetailcondition` (`homestuffdetailid`, `groupid`, `columns`, `value`, `comparator`)
		SELECT @homestuffdetailid, '1', @approve_column, '', '';


		SELECT CONCAT('增加成功') AS 操作说明;
	ELSE
		SELECT  CONCAT('简报已存在，请修改变量 @jianbao_label') AS 操作说明;
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for add_subtotal_field_bill_20240903
-- ----------------------------
DROP PROCEDURE IF EXISTS `add_subtotal_field_bill_20240903`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `add_subtotal_field_bill_20240903`(
    var_moudule varchar(100)
)
BEGIN
	DECLARE var_module varchar(100);
	DECLARE var_sourcemodule varchar(100);
	DECLARE var_tabid INT(100);
	declare done  int  default 0;
	declare cur1 CURSOR FOR select ld_option_module.tabid as tabid,`name` as sourcemodule from ld_option_module
                                                                                                                                                   INNER JOIN ld_tab ON ld_tab.tabid=ld_option_module.option_tabid
                            where ld_option_module.tabid=(SELECT tabid  from ld_tab WHERE `name`=var_moudule) and option_tabid NOT IN(SELECT tabid from ld_tab where `name` in ('PaymentPlan','SendPayment'));
declare continue handler  for not   found  SET done =1;

OPEN cur1;

Fetch cur1 into var_tabid,var_sourcemodule;
loop1: while  done<>1 DO
		SET @sourcemodule = var_sourcemodule;
		SET @tabid = var_tabid;
		SET @maxproducttoolfieldid = (SELECT max(producttoolfieldid) FROM ld_producttoolfield );
		SET @columnname = 'subtotal';
		SET @tablename = (SELECT tablename FROM ld_field WHERE tabid = @tabid and columnname ='smownerid');
		SET @trantable='ld_producttoolfield';
		SET @zh='小计';
		SET @en='Sub Total';

		SET @maxsequence = (SELECT max(sequence) FROM ld_producttoolfield WHERE tabid=@tabid);
		SET @fieldid = (select fieldid from ld_field where columnname = 'subtotal' and tabid=@tabid);
INSERT INTO `ld_producttoolfield` (`producttoolfieldid`, `columnname`, `allowhide`, `fieldlabel`, `defaultvalue`, `presence`, `uitype`, `typeofdata`, `sequence`, `tabid`, `tablename`, `width`, `edit_permission`, `input_type`, `fieldid`, `newline`, `defaultcolumn`, `is_checkimportfield`, `description`, `nullfield`, `referencemodule`, `datarange`, `approve_demand`, `maxrowsshow`, `bigtype`, `savedatabase`, `fieldvaluecolor`, `fieldplaceholder`, `effectivecondition`, `parentbigtype`, `sourcemodule`, `mobiledetailshow`, `relatedmodulefield`, `showhyperlinks`, `subtotal_attr`, `autowordwrap`, `editpage`)
SELECT @maxproducttoolfieldid+1,@columnname , 'yes', '小计', '0', '0', '33', 'N~O~25,2', @maxsequence+1, @tabid, @tablename, '22', '1', '0', @fieldid, '2', '3', '0', NULL, '1', NULL, NULL, NULL, '0', NULL, 'yes', NULL, NULL, NULL, NULL, @sourcemodule, NULL, 'no', 'yes', NULL, 'yes', NULL FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ld_producttoolfield WHERE tabid = @tabid AND columnname = @columnname AND sourcemodule=@sourcemodule);

SET @relateid=(SELECT producttoolfieldid FROM ld_producttoolfield WHERE tabid=@tabid AND columnname=@columnname AND sourcemodule=@sourcemodule LIMIT 1);
INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
SELECT 'zh',@trantable,@tabid,@relateid,@zh FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'zh' AND trantable =@trantable AND tabid = @tabid AND relateid=@relateid);

INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
SELECT 'en',@trantable,@tabid,@relateid,@en FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'en' AND trantable =@trantable AND tabid = @tabid AND relateid=@relateid);
Fetch cur1 into var_tabid,var_sourcemodule;
end while loop1;
close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for autocreatecashbillbycollectionslipwithdetail
-- ----------------------------
DROP PROCEDURE IF EXISTS `autocreatecashbillbycollectionslipwithdetail`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `autocreatecashbillbycollectionslipwithdetail`(collectionslip_id int(19))
BEGIN

	declare done  int  default 0;
  declare entitytype_info varchar(50);
	declare entitytypeid_info  int(11);
  declare amount_info decimal(25,8);

	declare cur2 CURSOR FOR SELECT entitytype,entitytypeid,amount   FROM  ld_collectionslipdetail where id=collectionslip_id;
	declare continue handler  for not   found  SET done =1;
  open cur2;
	fetch cur2 into entitytype_info,entitytypeid_info,amount_info;
	loop2: while  done<>1 DO

		  call createmodulebillno(@modulebillno);
			if entitytype_info='SalesOrder' then 
					select received_amount, total,signed_data ,currency_id,currency_symbol,conversion_rate   into  @source_received_amount,@source_total,@source_date, @source_currencyid,@source_currency_symbol,@source_conversion_rate
					 from ld_salesorder where salesorderid=entitytypeid_info;
			ELSEif entitytype_info='ServiceContracts' then 
				select received_amount ,total,due_date ,currency_id,currency_symbol,conversion_rate   into @source_received_amount, @source_total,@source_date, @source_currencyid,@source_currency_symbol,@source_conversion_rate
					 from ld_servicecontracts where servicecontractsid=entitytypeid_info;
			end if;
			 select max(maxcrmid) into @maxcrmid from (
			select max(crmid) as maxcrmid  from ld_crmentity 
			union all 
			select * from ld_crmentity_seq ) as tmp;
			 update ld_crmentity_seq set id=@maxcrmid+1;
			 insert into ld_crmentity(setype,crmid)value('CashBill',@maxcrmid+1);
			set @disable_triggers='aa';
			insert into ld_cashbill (cashbillid, smcreatorid,createdtime,modifiedtime,total,accountid,subtotal,currency_id,conversion_rate,currency_symbol ,cashbill_no
			,cashbilldate,cashtype,bankaccountsetid,smownerid,collectionslip_id,entitytype,source_list )
			select @maxcrmid+1,smownerid,now(),now(),total,accountid,total,currency_id,conversion_rate,currency_symbol
			,@modulebillno,remit_date,'cashbill',bankaccountsetid,smownerid,collectionslip_id,entitytype_info,entitytypeid_info from ld_collectionslip
			where ld_collectionslip.collectionslip_id=collectionslip_id;
		 
	   insert into ld_cashbillscf(cashbillid) value(@maxcrmid+1);
	   insert into ld_cashbill2paymentplan(cashbillid,amount,entitytype,entitytypeid,source_total,received_amount,currency_id,conversion_rate,currency_symbol,entitytype_value)value
			(@maxcrmid+1,amount_info,entitytype_info,entitytypeid_info,@source_total, @source_received_amount, @currencyid,@currency_symbol,@conversion_rate,@modulebillno);
		insert into ld_cashbill2paymentplanscf( cashbill2paymentplan_id)value( LAST_INSERT_ID());
		set @disable_triggers=null;
		update ld_cashbill set total=amount_info,subtotal=amount_info where cashbillid=@maxcrmid+1;
		fetch cur2 into entitytype_info,entitytypeid_info,amount_info;
	end while loop2;
	close cur2;

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for autocreatecashbillbycollectionsslip
-- ----------------------------
DROP PROCEDURE IF EXISTS `autocreatecashbillbycollectionsslip`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `autocreatecashbillbycollectionsslip`(
	collectionslip_id int(19)
)
begin
 

 call createmodulebillno(@modulebillno);
 select max(maxcrmid) into @maxcrmid from (
			select max(crmid) as maxcrmid  from ld_crmentity 
			union all 
			select * from ld_crmentity_seq ) as tmp;
			 update ld_crmentity_seq set id=@maxcrmid+1;
			 insert into ld_crmentity(setype,crmid)value('CashBill',@maxcrmid+1);
insert into ld_cashbill (cashbillid,smcreatorid,createdtime,modifiedtime,total,accountid,subtotal,currency_id,conversion_rate,currency_symbol ,cashbill_no,cashbilldate,cashtype,collectionslip_id
	,bankaccountsetid,smownerid)

select @maxcrmid+1,smownerid,now(),now(),total,accountid,total,currency_id,conversion_rate,currency_symbol
,@modulebillno,remit_date,'cashbill',bankaccountsetid ,collectionslip_id,smownerid from ld_collectionslip
where ld_collectionslip.collectionslip_id=collectionslip_id;

insert into ld_cashbillscf(cashbillid) select @maxcrmid+1;

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for autocreatecashbillbycollectionsslip_where
-- ----------------------------
DROP PROCEDURE IF EXISTS `autocreatecashbillbycollectionsslip_where`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `autocreatecashbillbycollectionsslip_where`(
	collectionslip_id int(19)
)
BEGIN 

	if exists(select * from  ld_collectionslipdetail   where  id=collectionslip_id) then 
		call autocreatecashbillbycollectionslipwithdetail(collectionslip_id);
	ELSE
		call autocreatecashbillbycollectionsslip(collectionslip_id);
	end if;

	update ld_collectionslip set collectionslip_status ='havecashbill' where collectionslip_id=collectionslip_id;

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for autodelete_operationtionlogs_procedure
-- ----------------------------
DROP PROCEDURE IF EXISTS `autodelete_operationtionlogs_procedure`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `autodelete_operationtionlogs_procedure`(
)
BEGIN

	set @delete_month =(SELECT deploy_value from ld_systems_deploy where deploy_type = 468);
	DELETE FROM ld_crmlog_entity WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);
	DELETE FROM ld_crmlog_create WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);
	DELETE FROM ld_crmlog_edit WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);
	DELETE FROM ld_crmlog_share WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);
	DELETE FROM ld_crmlog_delete WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for createmodulebillno
-- ----------------------------
DROP PROCEDURE IF EXISTS `createmodulebillno`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `createmodulebillno`(
	out modulebillno varchar(50)
)
begin 

	select concat( prefix , case when datetype = 'yyyymmdd' or  datetype = 'yyyymmdd-' then  DATE_FORMAT(now(),'%Y%m%d') 
			when datetype = 'yymm' or  datetype = 'yymm-'  or datetype = 'yymm.' 				then 		DATE_FORMAT(now(),'%Y%m') 
		  when datetype = 'yy-mm'  then  DATE_FORMAT(now(),'%Y-%m') 
		  when datetype = 'mmdd'  then  DATE_FORMAT(now(),'%m%d') 
			when datetype = 'mm-dd'  then  DATE_FORMAT(now(),'%m-%d')
		   when datetype = 'yyyy-mm-dd' or datetype = 'yyyy-mm-dd-'  then DATE_FORMAT(now(),'%Y-%m-%d')  
		 else  '' end,  case when right(datetype,1)='-' or right(datetype,1)='.' then right(datetype,1)
										else '' end ,

	case when ifnull(complement,0)>0 then LPAD(cur_id,complement,'0')
		else cur_id end ) into modulebillno
			from ld_modentity_num  where semodule='CashBill' and  active=1;
		

update ld_modentity_num set cur_id=case when ifnull(complement,0)>0 then LPAD(cur_id+1,complement,'0')
		else cur_id+1  end     
 where semodule='CashBill' and  active=1;
	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for crm_publicaccount_beforereminds
-- ----------------------------
DROP PROCEDURE IF EXISTS `crm_publicaccount_beforereminds`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `crm_publicaccount_beforereminds`()
BEGIN
	declare var_type varchar(100);
	DECLARE var_accountnames text;
	DECLARE var_totalaccounts int(19);
	declare var_smownerid int(19);
	declare var_ids text;

	declare parent_remindsid int(19); -- 父提醒id
	declare accountid int(19); -- 当前分割出的字符串(客户id)
	declare remindid int(19); -- 子提醒id
  declare i INT DEFAULT 1;

	declare done  int  default 0;
  declare cur1 CURSOR FOR select * from ld_publicaccount_remindtableview;
declare continue handler  for not   found  SET done =1;
OPEN cur1;

Fetch cur1 into var_type, var_accountnames,var_totalaccounts,var_smownerid,var_ids;
loop1: while  done<>1 DO
		set i=1;
		if var_totalaccounts>0 then
			if var_type='normal' or var_type='singlenormal' THEN
				set @tmpcontent=concat("您有",var_totalaccounts,"条普通客户未达成目标，即将要回收到公海池。客户名称如下：<br>",var_accountnames);
call ldcrm_add_reminder_havetype_returnid(@tmpcontent,var_smownerid,'Accounts',0,'AccountsBEFOREREMIND',parent_remindsid);
elseif var_type='complete' THEN
				set @tmpcontent=concat("您有",var_totalaccounts,"条公海客户达成条件后未达成目标，即将要回收到公海。客户名称如下：<br>",var_accountnames);
call ldcrm_add_reminder_havetype_returnid(@tmpcontent,var_smownerid,'Accounts',0,'AccountsBEFOREREMIND',parent_remindsid);
end if;

			-- 循环提取每个部分的accountid并生成提醒
			WHILE i <= var_totalaccounts DO
				SET accountid = SUBSTRING_INDEX(SUBSTRING_INDEX(var_ids, '##', i), '##', -1);
				-- 生成提醒
				set @remind_content="您的客户未达成目标，即将要被回收到公海池。";
call ldcrm_add_reminder_havetype_returnid(@remind_content,var_smownerid,'Accounts',accountid,'AccountsBEFOREREMIND',remindid);
update ld_reminds set deleted=1,parentid=parent_remindsid where remindsid=remindid;
SET i = i + 1;
END WHILE;
end if;
Fetch cur1 into var_type, var_accountnames,var_totalaccounts,var_smownerid,var_ids;
end while loop1;
close cur1;

end
;;
DELIMITER ;

