-- ----------------------------
-- Procedure structure for insert_module_signin_field
-- ----------------------------
DROP PROCEDURE IF EXISTS `insert_module_signin_field`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_module_signin_field`(
)
BEGIN
	
	
		declare tmp_option_tabid int;
		declare tmp_presence int;

		declare cur1 CURSOR FOR 
			SELECT
				option_tabid,
				ld_option_module.presence 
			FROM ld_option_module 
			LEFT JOIN ld_tab ON ld_tab.tabid = ld_option_module.tabid 
			WHERE `name` = 'Singin'
				AND option_tabid IN (SELECT tabid FROM ld_tab);

		DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_option_tabid = NULL;
	
		OPEN cur1;
		Fetch cur1 into tmp_option_tabid,tmp_presence;
		while(tmp_option_tabid is not null) DO
				select count(1) into @cnt from ld_field where tabid = tmp_option_tabid and bigtype = 'signin';
				if @cnt <=0 THEN
					UPDATE ld_field_seq SET id=(SELECT MAX(fieldid) FROM ld_field);
					select id + 1 into @fieldid from ld_field_seq;
					select block,tablename into @block,@tablename from ld_field where tabid = tmp_option_tabid and columnname = 'smownerid';
					select max(sequence) into @sequence from ld_field where block = @block;
					insert into ld_field(tabid,fieldid,columnname,allowhide,tablename,generatedtype,uitype,fieldname,fieldlabel,readonly,presence,defaultvalue,maximumlength,sequence,block,displaytype,
					typeofdata,quickcreate,quickcreatesequence,info_type,masseditable,helpinfo,fieldonly,issmownerid,searchfieldtype,associatedfields,associatedsequence,callchecked,
					duplicatefield,relate_search_parent_columnname,approve_demand,is_checkimportfield,allowedit,allowedit_presence,allowcreate,allowcreate_presence,allowdetail_presence,
					fldallow_rewriting,take_photo_only,savedatabase,bigtype,datarang,maxrowsshow,parentbigtype,profileeditfield,keywords,advance_demand,advance_demand_groups,uploadwatermark,
					fieldvaluecolor,fieldplaceholder,createdtime,modifiedtime,editpage,input_type,auto_signin,no_signin,allowable_distance) 
					values 
					(tmp_option_tabid,@fieldid,'signin_address','yes',@tablename,2,306,'signin_address','签到',0,tmp_presence,'',100,@sequence+1,@block,2,
					'V~O',0,0,'BAS',2,NULL,NULL,0,NULL,NULL,0,0,
					NULL,NULL,0,0,'no','no','no','no','yes',
					0,0,'no','signin','all',5,NULL,'yes',NULL,NULL,NULL,'no',
					'','',now(),now(),'','','NO','NO',0
					);
					insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
					select 'zh','ld_field',tmp_option_tabid,@fieldid,'签到' from dual 
					where not exists (select 1 from ld_tranlabel where languagetype='zh' and trantable='ld_field' and tabid = tmp_option_tabid and relateid=@fieldid);
					insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
					select 'en','ld_field',tmp_option_tabid,@fieldid,'Signin' from 
					dual where not exists (select * from ld_tranlabel where languagetype='en' and trantable='ld_field' and tabid = tmp_option_tabid and relateid=@fieldid);
					call AddColumn(@tablename,'signin_address','varchar','5',NULL);
					update ld_field_seq set id = (select max(fieldid) from ld_field);
				end if;
		Fetch cur1 into tmp_option_tabid,tmp_presence;
		end while;
		close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for insert_profileallpermission
-- ----------------------------
DROP PROCEDURE IF EXISTS `insert_profileallpermission`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_profileallpermission`(
	operationid VARCHAR(50)
)
BEGIN

	declare done  int  default 0;
	declare ttabid  int ;
	declare cur1 CURSOR FOR select tabid from ld_profileallpermission where operation = 1 GROUP BY tabid;
	declare continue handler  for not   found  SET done =1;

	OPEN cur1;
	Fetch cur1 into ttabid;
 	loop1: while  done<>1 DO
			set @sql=Concat('insert into ld_profileallpermission(tabid,operation,sequence) select ',ttabid,',',operationid,',',1000,' from dual where not exists(select 1 from ld_profileallpermission where tabid=',ttabid,' and operation=',operationid,')');
			prepare stmt from @sql;
			execute stmt;
			deallocate  prepare  stmt;
			set @i = 0;
			update ld_profileallpermission set sequence=(@i:=@i+1) where tabid=ttabid order by  Sequence asc ;
		Fetch cur1 into ttabid;
	end while loop1;
	close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for insert_tmp_date
-- ----------------------------
DROP PROCEDURE IF EXISTS `insert_tmp_date`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_tmp_date`(
)
BEGIN

	DECLARE tmpdate date default NULL;

	SET @cnt=0;
	SET @maxdate=(SELECT IFNULL(max(date),CURDATE()) FROM tmp_date);
	SET @mindate=(
		SELECT
			DATE_SUB(IFNULL(MIN(mindate),CURDATE()),INTERVAL 1 YEAR) 
		FROM (
				SELECT MIN(cashbilldate) AS mindate FROM ld_cashbill
				UNION
				SELECT DATE_FORMAT(MIN(createdtime),'%Y-%m-%d') AS mindate FROM ld_cashbill
				UNION
				SELECT MIN(signed_data) AS mindate FROM ld_salesorder
				UNION
				SELECT DATE_FORMAT(MIN(createdtime),'%Y-%m-%d') AS mindate FROM ld_salesorder
				UNION 
				SELECT MIN(due_date) AS mindate FROM ld_servicecontracts
				UNION
				SELECT DATE_FORMAT(MIN(createdtime),'%Y-%m-%d') AS mindate FROM ld_salesorder
			) a
		);
	SET @enddate=(SELECT CONCAT(YEAR(NOW())+1,'-12-31'));

	SET @cnt=(SELECT COUNT(1) FROM tmp_date);

	IF @cnt=0 THEN
		SET tmpdate=@mindate;
	ELSE
		SET tmpdate=DATE_ADD(@maxdate,INTERVAL 1 DAY);
	END IF;

	WHILE tmpdate<=@enddate DO
			INSERT INTO tmp_date(date) SELECT tmpdate;
			set tmpdate=DATE_ADD(tmpdate,INTERVAL 1 DAY);
	end while;

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_addcustomform_101to160
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_addcustomform_101to160`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_addcustomform_101to160`(
)
BEGIN

	declare i int default 101;

	SET @maxid=(SELECT MAX(parenttabid) FROM ld_parenttab);
	SET @seq=(SELECT MAX(sequence) FROM ld_parenttab);
INSERT INTO ld_parenttab(parenttabid,parenttab_label,sequence,visible,allocatetype)
SELECT @maxid+1,'CustomForms',@seq+1,0,'all' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ld_parenttab WHERE parenttab_label='CustomForms');

SET @myparenttabid=(SELECT parenttabid FROM ld_parenttab WHERE parenttab_label='CustomForms');
INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
SELECT 'zh','ld_parenttab',@myparenttabid, @myparenttabid,'自定义表单' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE tabid=@myparenttabid AND relateid=@fieldid AND languagetype='zh' AND trantable='ld_parenttab');
INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
SELECT 'en','ld_parenttab',@myparenttabid, @myparenttabid,'Custom Forms' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE tabid=@myparenttabid AND relateid=@fieldid AND languagetype='en' AND trantable='ld_parenttab');

WHILE i<=160 DO
		IF NOT EXISTS (SELECT 1 FROM ld_tab WHERE `name`=CONCAT('CustomForm',i)) THEN
			-- 添加模块
			CALL ldcrm_add_module_withoutdetail(CONCAT('CustomForm',i),CONCAT('自定义表单',i),CONCAT('Custom Form ',i),@myparenttabid);

			-- 添加审批流程
CALL ldcrm_add_approveforbill(CONCAT('CustomForm',i),260+i);
CALL AddColumn(CONCAT('ld_',LOWER('CustomForm'),i),'advance_stage','VARCHAR','100','');
CALL AddColumn(CONCAT('ld_',LOWER('CustomForm'),i),'kis_id','int','11',0);
CALL AddColumn(CONCAT('ld_',LOWER('CustomForm'),i),'kis_no','varchar','50',NULL);
END IF;
		SET i=i+1;
END WHILE;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_addmodule_bireportscreen
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_addmodule_bireportscreen`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_addmodule_bireportscreen`(
)
BEGIN
    IF NOT EXISTS (select 1 from ld_tab where `name`='BIReportScreen') THEN

        select tabsequence,tabid into @tabsequence,@hometabid from ld_tab where `name` = 'ReportAnalysis';
        update ld_tab set tabsequence := tabsequence + 1 where tabsequence > @tabsequence;
        select parenttabid,sequence into @parenttabid,@homeseq from ld_parenttabrel where tabid = @hometabid limit 1;
        update ld_parenttabrel set sequence := sequence + 1 where sequence > @homeseq;

        select max(tabid) + 1 into @newtabid from ld_tab;

        insert into ld_tab(tabid,`name`,presence,tabsequence,tablabel,printtab )
        select @newtabid,'BIReportScreen',0,@tabsequence+1,'BIReportScreen',1 from dual
        where not EXISTS(select 1 from ld_tab where `name`='BIReportScreen');

        insert into ld_parenttabrel(parenttabid,tabid,sequence) value (@parenttabid,@newtabid,@homeseq+1);

        insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
        select 'zh','ld_tab',@newtabid,@newtabid,'数字大屏' from dual
        where not exists(select 1 from ld_tranlabel where tabid=@newtabid and relateid=@newtabid and languagetype='zh'and trantable='ld_tab' );
        insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
        select 'en','ld_tab',@newtabid,@newtabid,'Home Data Cockpit' from dual
        where not exists(select 1 from ld_tranlabel where tabid=@newtabid and relateid=@newtabid and languagetype='en' and trantable='ld_tab');

        CREATE TABLE if not EXISTS `ld_bireportscreen` (
           `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
           `project_id` varchar(255) NOT NULL COMMENT '大屏id',
           `project_name` varchar(255) COMMENT '大屏名称',
           `deleted` int(11) DEFAULT 0 COMMENT '是否删除',
           `smcreatorid` int(11) COMMENT '创建用户',
           `createdtime` datetime COMMENT '创建时间',
           `scope` varchar(20) COMMENT '分配类型',
           `index_image` varchar(255) COMMENT '封面图片地址',
           `remarks` text  COMMENT '描述',
           PRIMARY KEY (`id`)
        ) ENGINE=InnoDB;
    END IF;
end
;;
DELIMITER ;

