-- ----------------------------
-- Procedure structure for ldcrm_add_email_new
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_email_new`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_email_new`(
	tmp_subject text,
	tmp_content text,
	tmp_toemail text,
	tmp_ccemail text,
	tmp_filepath text,
	tmp_sendtime datetime,
	tmp_sender int(19)
)
BEGIN
	

		-- 参数名称：tmp_toemail，接收人，多个用逗号分隔。例如：luyx@51mis.com,boss_28007@163.com
		-- 参数名称：tmp_ccemail，抄送人，多个用逗号分隔，没有可传空值。例如：luyx@51mis.com,boss_28007@163.com
		
		-- 参数名称：tmp_filepath，附件路径，需包含附件名称、必须在CRM安装目录下、只写CRM目录下的相对路径，没有可传空值。
		-- 例如： CRM安装路径 /home/www/crm/
		-- 附件： /home/www/crm/storage/2024/May/6/Centos7配置firewalld_6381_1.txt
		-- 取值： storage/2024/May/6/Centos7配置firewalld_6381_1.txt

		
		-- 邮件自动发送：可自行添加计划任务定时访问 modules/Reminds/sendRemindsEmail.php
		
		IF LENGTH(tmp_toemail)>5 THEN 
			IF IFNULL(tmp_filepath,'')<>'' THEN
				SET @email_fileid=IFNULL((SELECT MAX(crmid) FROM ld_crmentity),0)+1;
				INSERT INTO ld_crmentity(crmid,setype) SELECT @email_fileid,'Emails Attachment';
				UPDATE ld_crmentity_seq SET id=(SELECT max(crmid) FROM ld_crmentity); 

			
				-- 1、根据附件路径分隔附件名称和路径
				SET @reverse_path=REVERSE(tmp_filepath);
				SET @email_filename=REVERSE(LEFT(@reverse_path,LOCATE('/',@reverse_path)-1));
				SET @email_filepath=REVERSE(RIGHT(@reverse_path,CHAR_LENGTH(@reverse_path)-LOCATE('/',@reverse_path)+1));

				-- 2、根据附件名称中的后缀获取附件类型
				IF RIGHT(@email_filename,4)='.txt' THEN
					SET @email_filetype='text/plain';
				ELSEIF RIGHT(@email_filename,4)='.pdf' THEN
					SET @email_filetype='application/pdf';

				ELSEIF RIGHT(@email_filename,4)='.zip' THEN
					SET @email_filetype='application/x-zip-compressed';
				ELSEIF RIGHT(@email_filename,4) IN ('.rar','.sql') THEN
					SET @email_filetype='application/octet-stream';

				ELSEIF RIGHT(@email_filename,4)='.doc' THEN
					SET @email_filetype='application/msword';
				ELSEIF RIGHT(@email_filename,5)='.docx' THEN
					SET @email_filetype='application/vnd.openxmlformats-officedocument.wordprocessingml.document';

				ELSEIF RIGHT(@email_filename,4)='.ppt' THEN
					SET @email_filetype='application/vnd.ms-powerpoint';
				ELSEIF RIGHT(@email_filename,5)='.pptx' THEN
					SET @email_filetype='application/vnd.openxmlformats-officedocument.presentationml.presentation';

				ELSEIF RIGHT(@email_filename,4)='.xls' THEN
					SET @email_filetype='application/vnd.ms-excel';
				ELSEIF RIGHT(@email_filename,5)='.xlsx' THEN
					SET @email_filetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

				ELSEIF RIGHT(@email_filename,4)='.png' THEN
					SET @email_filetype='image/png';
				ELSEIF RIGHT(@email_filename,4)='.bmp' THEN
					SET @email_filetype='image/bmp';
				ELSEIF RIGHT(@email_filename,4)='.gif' THEN
					SET @email_filetype='image/gif';
				ELSEIF RIGHT(@email_filename,4)='.jpg' THEN
					SET @email_filetype='image/jpeg';
				ELSEIF RIGHT(@email_filename,5)='.jpeg' THEN
					SET @email_filetype='image/jpeg';

				ELSE
					SET @email_filetype=NULL;
				END IF;

				-- 3、写入附件
				INSERT INTO ld_attachments(
					attachmentsid,
					name,
					description,
					type,
					path,
					imagefromtype
				)
				SELECT
					@email_fileid,
					@email_filename,
					'邮件附件',
					@email_filetype,
					@email_filepath,
					'Computer';
			END IF;

			-- 4、获取写入邮件ID
			SET @email_emailid=IFNULL((SELECT MAX(crmid) FROM ld_crmentity),0)+1;
			INSERT INTO ld_crmentity(crmid,setype) SELECT @email_emailid,'Emails';
			UPDATE ld_crmentity_seq SET id=(SELECT max(crmid) FROM ld_crmentity); 

			-- 5.写入邮件和附件关联表
			INSERT INTO ld_seattachmentsrel(crmid,attachmentsid) SELECT @email_emailid,@email_fileid;

			-- 6、写入邮件
			INSERT INTO ld_activity(activityid,`subject`,description,to_email,cc_email,date_start,smownerid,smcreatorid,activitytype,visibility,deleted)
			SELECT @email_emailid,tmp_subject,tmp_content,tmp_toemail,tmp_ccemail,tmp_sendtime,tmp_sender,tmp_sender,'Emails','公共',0;
			
			INSERT INTO ld_activitycf(activityid) SELECT @email_emailid;

			INSERT INTO ld_activity_reminder(activity_id,email_remind)
			SELECT @email_emailid,tmp_sendtime;
			
		END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_emali_cc
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_emali_cc`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_emali_cc`(
	tmp_subject text,
	tmp_content text,
	tmp_toemail text,
	tmp_ccemail text,
	tmp_sendtime datetime,
	tmp_sender int(19)
)
BEGIN
	
		IF LENGTH(tmp_toemail)>5 THEN 

			SET @tmpcrmid=(SELECT MAX(crmid) FROM ld_crmentity);
			
			INSERT INTO ld_crmentity(crmid,setype) SELECT @tmpcrmid+1,'Emails';

			UPDATE ld_crmentity_seq SET id=(SELECT max(crmid) FROM ld_crmentity); 

			INSERT INTO ld_activity(activityid,`subject`,description,to_email,cc_email,date_start,smownerid,smcreatorid,activitytype,visibility,deleted)
			SELECT @tmpcrmid+1,tmp_subject,tmp_content,tmp_toemail,tmp_ccemail,tmp_sendtime,tmp_sender,tmp_sender,'Emails','公共',0;
			
			INSERT INTO ld_activitycf(activityid) SELECT @tmpcrmid+1;

			INSERT INTO ld_activity_reminder(activity_id,email_remind)
			SELECT @tmpcrmid+1,tmp_sendtime;
			
		END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_holiday
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_holiday`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_holiday`(
	tmp_name VARCHAR(100),
  tmp_type VARCHAR(10),
	tmp_date DATE
)
BEGIN

		SET @autoadd_module='Holiday';
		SET @tmp_date=tmp_date;

		SET @tmp_title=CONCAT(DATE_FORMAT(tmp_date,'%Y年'),tmp_name,IF(tmp_type='休','放','补'),'假');
		
		IF NOT EXISTS (SELECT 1 FROM ld_holiday WHERE deleted=0 AND holiday_date=@tmp_date) THEN
			SET @autoadd_maxcrmid=(SELECT MAX(crmid) FROM ld_crmentity);
			INSERT INTO ld_crmentity(crmid,setype)
			SELECT @autoadd_maxcrmid+1,@autoadd_module;
			UPDATE ld_crmentity_seq SET id=(SELECT MAX(crmid) FROM ld_crmentity);

			INSERT INTO ld_holiday(
				holidayid,
				holidayno,

				
				holiday_title,
				holiday_name,
				holiday_date,
				wheatherholidays,
				holiday_type,
				deleted,
				
				smownerid,					
				smcreatorid,				
				modifiedby,					
				createdtime,				
				modifiedtime
			)
			SELECT
				@autoadd_maxcrmid+1,
				(SELECT CONCAT(prefix,cur_id) FROM ld_modentity_num WHERE semodule=@autoadd_module AND active=1),

				@tmp_title,
				tmp_name,
				tmp_date,
				IF(tmp_type='补','班','休'),
				'法定节假日',
				0,
				
				1,					
				1,				
				1,					
				NOW(),				
				NOW();
		
			UPDATE ld_modentity_num SET cur_id=cur_id+1 WHERE semodule=@autoadd_module AND active=1;

			INSERT INTO ld_holidayscf(holidayid) SELECT @autoadd_maxcrmid+1;

	END IF;
			
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_leads_fileld
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_leads_fileld`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_leads_fileld`()
BEGIN

	IF EXISTS (SELECT 1 FROM ld_tab WHERE name='Leads') THEN
		SET @modulename='Leads';
		SET @tabid=(SELECT tabid FROM ld_tab WHERE name=@modulename);
		SET @relateid=(select block from ld_field where columnname = 'smownerid' and tabid = @tabid);
		SET @maxseq=IFNULL((SELECT MAX(sequence) FROM ld_field WHERE tabid=@tabid AND block=@relateid),0);
		SET @trantable='ld_field';
		SET @tablename=(SELECT tablename FROM ld_field WHERE tabid=@tabid AND columnname='smownerid' LIMIT 1);
		SET @columnname='upgradeaccountid';
		SET @fieldname='upgradeaccountid';
		SET @zh='升级后客户';
		SET @en='Accounts after upgrade';
		SET @uitype=73;
		SET @typeofdata='V~O';
		SET @quickcreate=0;
		SET @displaytype=2;
		SET @bigtype='reference';
		SET @datarang=NULL;
		SET @maxrowsshow=0;
		SET @savedatabase = 'yes';
		SET @allowedit = 'no';
		SET @maxid=(SELECT MAX(fieldid) FROM ld_field);
		INSERT INTO ld_field(tabid,fieldid,columnname,tablename,generatedtype,uitype,fieldname,fieldlabel,readonly,presence,defaultvalue,maximumlength,sequence,block,displaytype,typeofdata,quickcreate,quickcreatesequence,info_type,masseditable,helpinfo,fieldonly,approve_demand,is_checkimportfield,bigtype,datarang,maxrowsshow,savedatabase,allowedit)
		SELECT @tabid,@maxid+1,@columnname,@tablename,1,@uitype,@fieldname,@zh,0,2,NULL,100,@maxseq+1,@relateid,@displaytype,@typeofdata,@quickcreate,NULL,NULL,1,NULL,0,2,0,@bigtype,@datarang,@maxrowsshow,@savedatabase,@allowedit from dual
		WHERE NOT EXISTS (SELECT 1 FROM ld_field WHERE tabid=@tabid AND tablename=@tablename AND columnname=@columnname);
		UPDATE ld_field_seq SET id=(SELECT max(fieldid) FROM ld_field);

		SET @relateid=(SELECT fieldid FROM ld_field WHERE tabid=@tabid AND columnname=@columnname LIMIT 1);
		INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
		SELECT 'zh',@trantable,@tabid,@relateid,@zh FROM DUAL
		WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'zh' AND trantable =@trantable AND tabid = @tabid AND relateid=@relateid);
		INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
		SELECT 'en',@trantable,@tabid,@relateid,@en FROM DUAL
		WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'en' AND trantable =@trantable AND tabid = @tabid AND relateid=@relateid);

		CALL AddColumn(@tablename,@columnname,'int','19','');

	END IF;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_producttotal_and_cumulativebenefits
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_producttotal_and_cumulativebenefits`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_producttotal_and_cumulativebenefits`()
BEGIN

    DECLARE tmptabid INT(11) DEFAULT 0;
    DECLARE tmpsourcemodule VARCHAR(50) DEFAULT '';
    DECLARE tmpuitype INT(10) DEFAULT 0;
    DECLARE tmptypeofdata VARCHAR(20) DEFAULT 'N~O~25,2';
    DECLARE tmptablename VARCHAR(50) DEFAULT 'ld_products';

    DECLARE MYCUSOR CURSOR FOR SELECT tabid,sourcemodule,uitype,typeofdata,tablename FROM ld_producttoolfield WHERE columnname = 'total';

    DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmptabid = NULL;

    OPEN MYCUSOR;
    FETCH MYCUSOR INTO tmptabid,tmpsourcemodule,tmpuitype,tmptypeofdata,tmptablename;
    WHILE(tmptabid IS NOT NULL) DO
			SET @disable_triggers=1;
            SET @producttoolfieldid=(SELECT MAX(producttoolfieldid)+1 FROM ld_producttoolfield);
            SET @columnname = 'product_licence_price';
            SET @trantable='ld_producttoolfield';
            SET @allowhide = 'no';
            SET @fieldlabel = '产品总价';
            SET @zh='产品总价';
            SET @en='Product licence price';
            SET @bigtype='currency';
            SET @parentbigtype='';
            SET @newline=1;
            SET @edit_permission=1;
            SELECT IFNULL(MAX(sequence),1) INTO @sequence FROM ld_producttoolfield where tabid=tmptabid;
            INSERT INTO ld_producttoolfield(producttoolfieldid,columnname,allowhide,fieldlabel,defaultvalue,presence,uitype,typeofdata,sequence,tabid,tablename,width,edit_permission,input_type, fieldid,newline,defaultcolumn,is_checkimportfield,nullfield,referencemodule,datarange,approve_demand,maxrowsshow,bigtype,savedatabase,parentbigtype,sourcemodule)
            SELECT @producttoolfieldid,@columnname,@allowhide,@fieldlabel,NULL,0,tmpuitype,tmptypeofdata,@sequence+1,tmptabid,tmptablename,45,@edit_permission,0,0,@newline,2,0,0,'','','',0,@bigtype,'yes',@parentbigtype,tmpsourcemodule FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_producttoolfield WHERE tabid=tmptabid AND columnname=@columnname AND tablename=tmptablename AND IFNULL(sourcemodule,1) = IFNULL(tmpsourcemodule,1) );

            SELECT producttoolfieldid INTO @relatedid FROM ld_producttoolfield WHERE tabid=tmptabid AND columnname=@columnname AND IFNULL(sourcemodule,1) = IFNULL(tmpsourcemodule,1) LIMIT 1;
            INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
            SELECT 'zh',@trantable,tmptabid,@relatedid,@zh FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'zh' AND tabid=tmptabid AND relateid=@relatedid AND trantable=@trantable);
            INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
            SELECT 'en',@trantable,tmptabid,@relatedid,@en FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'en' AND tabid=tmptabid AND relateid=@relatedid AND trantable=@trantable);

            CALL AddColumn (tmptablename,@columnname,'decimal','(25,8)',0);

            SET @exec_sql = CONCAT('UPDATE ',tmptablename,' SET ', @columnname, ' = total WHERE (total <> 0 OR total IS NOT NULL) AND ', @columnname, ' = 0');
            PREPARE mystmt FROM @exec_sql;
            EXECUTE mystmt;
            DEALLOCATE PREPARE mystmt;

            SET @producttoolfieldid=(SELECT MAX(producttoolfieldid)+1 FROM ld_producttoolfield);
            SET @columnname = 'cumulative_benefits';
            SET @trantable='ld_producttoolfield';
            SET @allowhide = 'no';
            SET @fieldlabel = '累计优惠';
            SET @zh='累计优惠';
            SET @en='Cumulative Benefits';
            SET @bigtype='currency';
            SET @parentbigtype='';
            SET @newline=1;
            SET @edit_permission=1;
            SELECT IFNULL(MAX(sequence),1) INTO @sequence FROM ld_producttoolfield where tabid=tmptabid;
            INSERT INTO ld_producttoolfield(producttoolfieldid,columnname,allowhide,fieldlabel,defaultvalue,presence,uitype,typeofdata,sequence,tabid,tablename,width,edit_permission,input_type, fieldid,newline,defaultcolumn,is_checkimportfield,nullfield,referencemodule,datarange,approve_demand,maxrowsshow,bigtype,savedatabase,parentbigtype,sourcemodule)
            SELECT @producttoolfieldid,@columnname,@allowhide,@fieldlabel,NULL,0,tmpuitype,tmptypeofdata,@sequence+1,tmptabid,tmptablename,45,@edit_permission,0,0,@newline,2,0,0,'','','',0,@bigtype,'yes',@parentbigtype,tmpsourcemodule FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_producttoolfield WHERE tabid=tmptabid AND columnname=@columnname AND tablename=tmptablename AND IFNULL(sourcemodule,1) = IFNULL(tmpsourcemodule,1) );

            SELECT producttoolfieldid INTO @relatedid FROM ld_producttoolfield WHERE tabid=tmptabid AND columnname=@columnname AND IFNULL(sourcemodule,1) = IFNULL(tmpsourcemodule,1) LIMIT 1;
            INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
            SELECT 'zh',@trantable,tmptabid,@relatedid,@zh FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'zh' AND tabid=tmptabid AND relateid=@relatedid AND trantable=@trantable);
            INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
            SELECT 'en',@trantable,tmptabid,@relatedid,@en FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'en' AND tabid=tmptabid AND relateid=@relatedid AND trantable=@trantable);

            CALL AddColumn (tmptablename,@columnname,'decimal','(25,8)',0);

            UPDATE ld_producttoolfield a
                LEFT JOIN ld_producttoolfield b ON b.tabid = a.tabid AND b.tablename = a.tablename AND IFNULL(b.sourcemodule,1) = IFNULL(a.sourcemodule,1) AND b.columnname = 'cumulative_benefits'
            SET a.sequence = (b.sequence+1) WHERE a.columnname='total';

            UPDATE ld_producttoolfield_seq SET ld_producttoolfield_seq.id=(SELECT MAX(producttoolfieldid) FROM ld_producttoolfield);
			SET @disable_triggers=NULL;
            FETCH MYCUSOR INTO tmptabid,tmpsourcemodule,tmpuitype,tmptypeofdata,tmptablename;
        END WHILE;

    CLOSE MYCUSOR;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_profile_for_bireportscreen
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_profile_for_bireportscreen`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_profile_for_bireportscreen`()
BEGIN

    DECLARE tmp_profileid INT(19) DEFAULT 0;

    DECLARE MYCUSOR CURSOR FOR SELECT profileid FROM ld_profile WHERE profileid>0;

    DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_profileid = NULL;

    SET @tabid=(select tabid from ld_tab  where name='BIReportScreen');

    set @operation = (SELECT actionid from ld_actionmapping where actionname = 'index');

    IF NOT EXISTS (SELECT 1 FROM ld_profileallpermission WHERE tabid=@tabid) THEN
        INSERT INTO ld_profileallpermission(tabid,operation,sequence) VALUES (@tabid,@operation,0);
    END IF;

        IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid) THEN
            OPEN MYCUSOR;
            FETCH MYCUSOR INTO tmp_profileid;
            WHILE(tmp_profileid IS NOT NULL) DO
                    SET @profileid=tmp_profileid;
                    INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
                    SELECT
                        @profileid AS profileid,
                        @tabid AS tabid,
                        @operation,
                        0,
                        0
                    FROM ld_profile2standardpermissions a
                             LEFT JOIN ld_tab b ON b.tabid=a.tabid
                    WHERE a.profileid=@profileid
                      AND a.operation=@operation
                    LIMIT 1;

                    SET @i=0;
                    UPDATE ld_profile2standardpermissions SET sequence=(@i:=@i+1) WHERE tabid=@tabid AND profileid=@profileid ORDER BY sequence;

                    IF NOT EXISTS (SELECT 1 FROM ld_profile2tab WHERE tabid=@tabid AND profileid=@profileid) THEN
                        INSERT INTO ld_profile2tab(profileid,tabid,permissions)
                        SELECT profileid,@tabid,IF(MIN(permissions)=0,1,0) FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid;
                    END IF;

                    IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid AND permissions=0) THEN
                        UPDATE ld_profile2standardpermissions SET permissions=1 WHERE tabid=@tabid AND profileid=@profileid AND operation=0;
                    END IF;

                    FETCH MYCUSOR INTO tmp_profileid;
                END WHILE;
            CLOSE MYCUSOR;
        END IF;
    END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_profile_for_default
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_profile_for_default`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_profile_for_default`(in `tmp_tabname` varchar(50) , in `tmp_actionname` varchar(200))
BEGIN

	DECLARE tmp_profileid INT(19) DEFAULT 0;

	DECLARE MYCUSOR CURSOR FOR SELECT profileid FROM ld_profile WHERE profileid>0;

DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_profileid = NULL;

	SET @tabid=(select tabid from ld_tab  where name=`tmp_tabname`);

	set @operation = (SELECT actionid from ld_actionmapping where actionname = `tmp_actionname`);

	IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid and operation = @operation) THEN
		OPEN MYCUSOR;
FETCH MYCUSOR INTO tmp_profileid;
WHILE(tmp_profileid IS NOT NULL) DO
			SET @profileid=tmp_profileid;
INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
SELECT
    @profileid AS profileid,
    @tabid AS tabid,
    @operation,
    0,
    0
FROM ld_profile2standardpermissions a
         LEFT JOIN ld_tab b ON b.tabid=a.tabid
WHERE a.profileid=@profileid
  AND a.operation=@operation
    LIMIT 1;

SET @i=0;
UPDATE ld_profile2standardpermissions SET sequence=(@i:=@i+1) WHERE tabid=@tabid AND profileid=@profileid ORDER BY sequence;

IF NOT EXISTS (SELECT 1 FROM ld_profile2tab WHERE tabid=@tabid AND profileid=@profileid) THEN
				INSERT INTO ld_profile2tab(profileid,tabid,permissions)
SELECT profileid,@tabid,IF(MIN(permissions)=0,1,0) FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid;
END IF;

			IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid AND permissions=0) THEN
UPDATE ld_profile2standardpermissions SET permissions=1 WHERE tabid=@tabid AND profileid=@profileid AND operation=0;
END IF;

FETCH MYCUSOR INTO tmp_profileid;
END WHILE;
CLOSE MYCUSOR;
END IF;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_profile_for_default_print
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_profile_for_default_print`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_profile_for_default_print`(in tmp_tabid int(19) , in `tmp_operation` int(19))
BEGIN

	DECLARE tmp_profileid INT(19) DEFAULT 0;

	DECLARE MYCUSOR CURSOR FOR SELECT profileid FROM ld_profile WHERE profileid>0;

DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_profileid = NULL;

	SET @tabid=tmp_tabid;

	set @operation = tmp_operation;

OPEN MYCUSOR;
FETCH MYCUSOR INTO tmp_profileid;
WHILE(tmp_profileid IS NOT NULL) DO
		SET @profileid=tmp_profileid;
		IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid and operation = @operation and profileid = @profileid)
		THEN
			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
SELECT
    @profileid AS profileid,
    @tabid AS tabid,
    @operation,
    0,
    0
FROM ld_profile2standardpermissions a
         LEFT JOIN ld_tab b ON b.tabid=a.tabid
WHERE a.profileid=@profileid
  AND a.operation=@operation
    LIMIT 1;
END IF;

		SET @i=0;
UPDATE ld_profile2standardpermissions SET sequence=(@i:=@i+1) WHERE tabid=@tabid AND profileid=@profileid ORDER BY sequence;

IF NOT EXISTS (SELECT 1 FROM ld_profile2tab WHERE tabid=@tabid AND profileid=@profileid) THEN
			INSERT INTO ld_profile2tab(profileid,tabid,permissions)
SELECT profileid,@tabid,IF(MIN(permissions)=0,1,0) FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid;
END IF;

		IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid AND permissions=0) THEN
UPDATE ld_profile2standardpermissions SET permissions=1 WHERE tabid=@tabid AND profileid=@profileid AND operation=0;
END IF;

FETCH MYCUSOR INTO tmp_profileid;
END WHILE;
CLOSE MYCUSOR;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_profile_for_print
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_profile_for_print`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_profile_for_print`()
BEGIN


	DECLARE tmp_tabid int(19) DEFAULT '';

	DECLARE MYCUSOR CURSOR FOR (
		SELECT ld_profileallpermission.tabid from ld_profileallpermission
		INNER JOIN ld_tab on ld_tab.tabid = ld_profileallpermission.tabid
		WHERE operation = (SELECT actionid from ld_actionmapping where actionname = 'Print') );

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_tabid = NULL;

SELECT actionid INTO @operation from ld_actionmapping where actionname = 'Print';
IF NOT EXISTS (SELECT 1 FROM ld_crmentity WHERE crmid > 2) THEN
	OPEN MYCUSOR;
FETCH MYCUSOR INTO tmp_tabid;
WHILE(tmp_tabid IS NOT NULL) DO
		CALL ldcrm_add_profile_for_default_print(tmp_tabid,@operation);

FETCH MYCUSOR INTO tmp_tabid;
END WHILE;
CLOSE MYCUSOR;
END IF;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_profile_for_reportanalysis
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_profile_for_reportanalysis`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_profile_for_reportanalysis`(
)
BEGIN

	DECLARE tmp_profileid INT(19) DEFAULT 0;

	DECLARE MYCUSOR CURSOR FOR SELECT profileid FROM ld_profile WHERE profileid>0;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_profileid = NULL;

	SET @tabid=(SELECT tabid FROM ld_tab WHERE `name`='ReportAnalysis');

	IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid) THEN
		OPEN MYCUSOR;
		FETCH MYCUSOR INTO tmp_profileid;
		WHILE(tmp_profileid IS NOT NULL) DO
			SET @profileid=tmp_profileid;
			
			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
			SELECT
				@profileid AS profileid,
				@tabid AS tabid,
				3,
				0,
				0
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE b.`name` IN ('Customreport','OftenUseReport','CustomEcharts','CustomTables','Comprehensivereport')
				AND a.profileid=@profileid
				AND a.operation=3
			LIMIT 1;


			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
			SELECT
				@profileid AS profileid,
				@tabid AS tabid,
				1,
				IFNULL(MIN(a.permissions),1),
				101
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE b.`name` IN ('Customreport','OftenUseReport','CustomEcharts','CustomTables','Comprehensivereport')
				AND a.profileid=@profileid
				AND a.operation=11;

			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
			SELECT
				@profileid AS profileid,
				@tabid AS tabid,
				11,
				IFNULL(MIN(a.permissions),1),
				201
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE b.`name` IN ('Customreport','OftenUseReport','CustomEcharts','CustomTables','Comprehensivereport')
				AND a.profileid=@profileid
				AND a.operation=11;

			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
			SELECT
				@profileid AS profileid,
				@tabid AS tabid,
				2,
				IFNULL(MIN(a.permissions),1),
				301
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE b.`name` IN ('Customreport','OftenUseReport','CustomEcharts','CustomTables','Comprehensivereport')
				AND a.profileid=@profileid
				AND a.operation=2;

			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
			SELECT
				@profileid AS profileid,
				@tabid AS tabid,
				13,
				IFNULL(MIN(a.permissions),1),
				401
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE b.`name` IN ('Customreport','OftenUseReport','CustomEcharts','CustomTables','Comprehensivereport')
				AND a.profileid=@profileid
				AND a.operation=13;

			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
			SELECT
				@profileid AS profileid,
				@tabid AS tabid,
				6,
				IFNULL(MIN(a.permissions),1),
				501
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE b.`name` IN ('Customreport','OftenUseReport','CustomEcharts','CustomTables','Comprehensivereport')
				AND a.profileid=@profileid
				AND a.operation=44;

			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
			SELECT
				@profileid AS profileid,
				@tabid AS tabid,
				45,
				IFNULL(MIN(a.permissions),1),
				601
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE b.`name` IN ('Customreport','OftenUseReport','CustomEcharts','CustomTables','Comprehensivereport')
				AND a.profileid=@profileid
				AND a.operation=45;
			
			SET @i=0;
			UPDATE ld_profile2standardpermissions SET sequence=(@i:=@i+1) WHERE tabid=@tabid AND profileid=@profileid ORDER BY sequence;

			IF NOT EXISTS (SELECT 1 FROM ld_profile2tab WHERE tabid=@tabid AND profileid=@profileid) THEN
				INSERT INTO ld_profile2tab(profileid,tabid,permissions)
				SELECT profileid,@tabid,IF(MIN(permissions)=0,1,0) FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid;
			END IF;

			IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid AND permissions=0) THEN
				UPDATE ld_profile2standardpermissions SET permissions=1 WHERE tabid=@tabid AND profileid=@profileid AND operation=0;
			END IF;

			FETCH MYCUSOR INTO tmp_profileid;
		END WHILE;
		CLOSE MYCUSOR;
	END IF;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_profile_for_visualanalysis
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_profile_for_visualanalysis`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_profile_for_visualanalysis`(
)
BEGIN

	DECLARE tmp_profileid INT(19) DEFAULT 0;

	DECLARE MYCUSOR CURSOR FOR SELECT profileid FROM ld_profile WHERE profileid>0;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_profileid = NULL;

	SET @tabid=(select tabid from ld_tab  where name='VisualAnalysis');

	set @operation = (SELECT actionid from ld_actionmapping where actionname = 'DetailView');

	IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid) THEN
		OPEN MYCUSOR;
			FETCH MYCUSOR INTO tmp_profileid;
			WHILE(tmp_profileid IS NOT NULL) DO
			SET @profileid=tmp_profileid;

			INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
			SELECT
					@profileid AS profileid,
					@tabid AS tabid,
					@operation,
					0,
					0
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE a.profileid=@profileid
				AND a.operation=@operation
					LIMIT 1;

			SET @i=0;
			UPDATE ld_profile2standardpermissions SET sequence=(@i:=@i+1) WHERE tabid=@tabid AND profileid=@profileid ORDER BY sequence;

			IF NOT EXISTS (SELECT 1 FROM ld_profile2tab WHERE tabid=@tabid AND profileid=@profileid) THEN
				INSERT INTO ld_profile2tab(profileid,tabid,permissions)
				SELECT profileid,@tabid,IF(MIN(permissions)=0,1,0) FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid;
			END IF;

			IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid AND permissions=0) THEN
				UPDATE ld_profile2standardpermissions SET permissions=1 WHERE tabid=@tabid AND profileid=@profileid AND operation=0;
			END IF;

			FETCH MYCUSOR INTO tmp_profileid;
		END WHILE;
		CLOSE MYCUSOR;
	END IF;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_reminder
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_reminder`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_reminder`(
	tmp_content text,
	tmp_recieverid TEXT,
	tmp_reltab VARCHAR(100),
	tmp_related_to INT(19)
)
BEGIN

	DECLARE tmp_userid INT(19) DEFAULT 0;

	DECLARE MYCUSOR CURSOR FOR 
		SELECT 
			DISTINCT substring_index(substring_index(a.mytext,',', b.seq+1 ),',',- 1) AS mytext
		FROM (SELECT tmp_recieverid AS mytext) a
		LEFT JOIN sequence b ON b.seq <(length(a.mytext) - length( REPLACE(a.mytext,',',''))+1) 
		WHERE substring_index(substring_index(a.mytext,',', b.seq+1 ),',',- 1)+0>0
		ORDER BY b.seq;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_userid = NULL;


	OPEN MYCUSOR; 
	FETCH MYCUSOR INTO tmp_userid;
	WHILE(tmp_userid IS NOT NULL) DO
	
		SET @max_remindid=(SELECT MAX(crmid) FROM ld_crmentity);
		IF EXISTS (SELECT 1 FROM ld_crmentity WHERE crmid=@max_remindid+1) OR EXISTS (SELECT 1 FROM ld_reminds WHERE remindsid=@max_remindid+1) OR EXISTS (SELECT 1 FROM ld_reminds_accepted WHERE remindsid=@max_remindid+1) THEN
			SET @max_remindid=(SELECT MAX(crmid)+10 FROM ld_crmentity); 
		END IF;

		INSERT INTO ld_crmentity(crmid,setype)
		SELECT @max_remindid+1,'Reminds';		

		UPDATE ld_crmentity_seq SET id=(SELECT MAX(crmid) FROM ld_crmentity);
		
		INSERT INTO ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
		SELECT @max_remindid+1,tmp_content,now(),tmp_userid,'未读',tmp_related_to,tmp_reltab,0,0,0,0,0,0,now(),now(),null,0;
		
		FETCH MYCUSOR INTO tmp_userid;
	END WHILE;
	CLOSE MYCUSOR;


end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_reminder_havetype
