-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_reminder_havetype_returnid`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_reminder_havetype_returnid`(
    tmp_content text,
