-- ----------------------------
-- Procedure structure for ldcrm_add_sms
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_sms`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_add_sms`(
	tmp_mobile VARCHAR(50),
	tmp_jieshouren VARCHAR(255),
	tmp_content TEXT,
	tmp_sendtime DATETIME,
	tmp_sender VARCHAR(100),
	tmp_relatedid INT(19)
)
BEGIN

	SET @cnt=(SELECT COUNT(SubmitTime) FROM ld_smssend WHERE DATE_FORMAT(SubmitTime,'%Y-%m-%d')=CURDATE());

	INSERT INTO ld_smssend(
		TaskID,
		BatchNo,
		CalledNumber,
		SmsContent,
		SubmitTime,
		CreateTime,
		SmsResult,
		SmsBillingFee,
		operator,
		ReceiveContacts,
		FDataStatu,
		relatieid
	)
	SELECT
		IFNULL((SELECT MAX(TaskID) FROM ld_smssend),0)+1,
		CONCAT('sms',DATE_FORMAT(NOW(),'%Y%m%d'),LPAD(@cnt+1,8,0)),
		tmp_mobile,
		tmp_content,
		tmp_sendtime,
		NOW(),
		0,
		0.00,
		tmp_sender,
		tmp_jieshouren,
		0,
		tmp_relatedid;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_clean_reminds
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_clean_reminds`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_clean_reminds`(
	tmp_date DATE
)
BEGIN

	DECLARE i INT(19) DEFAULT 0;
	
	SET @this_tmpdate=tmp_date;
	
	WHILE(i>=0) DO
		IF EXISTS (SELECT 1 FROM ld_reminds WHERE date_time<=@this_tmpdate LIMIT 1) THEN
			DELETE FROM ld_reminds WHERE date_time<=@this_tmpdate LIMIT 5000;
			DELETE FROM ld_reminds_accepted WHERE date_time<@this_tmpdate LIMIT 5000;
			DELETE FROM ld_crmentity WHERE setype='Reminds' AND crmid NOT IN (SELECT remindsid FROM ld_reminds UNION SELECT remindsid FROM ld_reminds_accepted) LIMIT 10000;		
		
			SET i=i+1;
		ELSE
			SET i=-1;
		END IF;
		
	END WHILE;


end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_defaultcreateprofileon
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_defaultcreateprofileon`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_defaultcreateprofileon`(
    modulename varchar(50),
    permissions int(19)
)
begin
	declare done int default 0;
	declare pprofileid  int ;
	declare cur1 CURSOR FOR SELECT profileid FROM ld_profile where profileid!=1;-- 总经理字段需要所有权限 之后统一添加
declare continue handler  for not   found  SET done =1;
	set @sql = concat('select tabid into @tabid from ld_tab where name=','''',modulename,'''');
prepare stmt from @sql;
execute stmt;
deallocate  prepare stmt;
OPEN cur1;
Fetch cur1 into pprofileid;
loop1: while  done<>1 DO
	set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',4,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=4)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',11,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=11)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
Fetch cur1 into pprofileid;
end while loop1;
close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_read_tmpreminder
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_read_tmpreminder`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_read_tmpreminder`(
)
BEGIN
	DECLARE tmp_id INT(19) DEFAULT 0;
	DECLARE tmp_content text DEFAULT '';
	DECLARE tmp_recieverid INT(19) DEFAULT 0;
	DECLARE tmp_remindtime datetime;
	DECLARE tmp_reltab varchar(100) DEFAULT '';
	DECLARE tmp_related_to INT(19) DEFAULT 0;
	DECLARE tmp_ruleid INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR 
		SELECT
			id,
			content,
			reminderid,
			remindtime,
			reltab,
			related_to,
			reminds_ruleid 
		FROM ld_tmpreminder 
		WHERE remindtime<=NOW() 
			AND IFNULL(content,'') not like '%[var.%'
		ORDER BY remindtime DESC LIMIT 50;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	OPEN Mycur;
	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	WHILE (tmp_id IS NOT NULL) DO
		DELETE FROM ld_tmpreminder WHERE id=tmp_id;
		set @maxid=0;
		select max(crmid) into @maxid from ld_crmentity;
		insert into ld_crmentity(crmid,setype)
		select @maxid+1,'Reminds';
		
		update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			
		insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
		select @maxid+1,tmp_content,tmp_remindtime,tmp_recieverid,'未读',tmp_related_to,tmp_reltab,0,0,tmp_ruleid,0,0,0,tmp_remindtime,tmp_remindtime,null,0
		from dual where not exists (select 1 from ld_reminds where content=tmp_content AND recieverid=tmp_recieverid and related_to=tmp_related_to and date_time=tmp_remindtime and reminds_ruleid=tmp_ruleid);

	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	END WHILE;
	CLOSE Mycur;	
	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_refresh_advance_stage
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_refresh_advance_stage`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_refresh_advance_stage`()
BEGIN

	DECLARE tmp_tablename varchar(50) DEFAULT '';
	DECLARE tmp_fieldname varchar(100) DEFAULT '';
	DECLARE tmp_dir_tablename varchar(50) DEFAULT '';
	DECLARE tmp_entityidfield varchar(150) DEFAULT '';

	DECLARE MYCUSOR CURSOR FOR
        SELECT
            (SELECT tablename FROM ld_field a WHERE tabid=ld_settings_advance.tabid AND columnname='createdtime') AS `tablename`,
            ld_field.`columnname` ,
            ld_field.`tablename` as `dir_tablename`,
            ld_entityname.entityidfield
        FROM ld_settings_advance
        LEFT JOIN ld_field ON ld_field.tabid = ld_settings_advance.tabid AND ld_field.fieldname = ld_settings_advance.module_field
        LEFT JOIN ld_entityname on ld_entityname.tabid = ld_settings_advance.tabid
        WHERE (`enable` = 'yes' or `showadvancemobile` = 'yes');
    DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_tablename = NULL,tmp_fieldname = NULL;

	set @disable_triggers = 'ldcrm_refresh_advance_stage';

    OPEN MYCUSOR;
    FETCH MYCUSOR INTO tmp_dir_tablename,tmp_fieldname,tmp_tablename,tmp_entityidfield;
    WHILE(tmp_tablename IS NOT NULL) DO
        SET @update_sql = (
                    CASE
                        WHEN tmp_tablename = tmp_dir_tablename THEN CONCAT("UPDATE ",tmp_dir_tablename," SET advance_stage = ",tmp_fieldname," WHERE deleted=0 AND advance_stage <> ",tmp_fieldname,";")
                        ELSE CONCAT("UPDATE ",tmp_dir_tablename," LEFT JOIN ",tmp_tablename," ON ",tmp_tablename,".",tmp_entityidfield," = ",tmp_dir_tablename,".",tmp_entityidfield," SET advance_stage = ",tmp_fieldname," WHERE deleted=0 AND advance_stage <> ",tmp_fieldname,";")
                    END
                );
        PREPARE stmtt FROM @update_sql;
        EXECUTE stmtt;
        DEALLOCATE PREPARE stmtt;

        FETCH MYCUSOR INTO tmp_dir_tablename,tmp_fieldname,tmp_tablename,tmp_entityidfield;
    END WHILE;
    CLOSE MYCUSOR;

    set @disable_triggers = NULL;

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_remindsdata_delete
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_remindsdata_delete`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_remindsdata_delete`(
)
BEGIN

	DECLARE tmp_deldataids MEDIUMTEXT DEFAULT NULL;

	
	DECLARE REMIND_DELCUSOR CURSOR FOR 
		SELECT
			GROUP_CONCAT(remindsid) AS ids
		FROM (
			SELECT 
				remindsid
			FROM ld_reminds_accepted 
			WHERE date_time<DATE_SUB(CURDATE(),INTERVAL 3 MONTH)
			LIMIT 200
		) a;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_deldataids = NULL;

	OPEN REMIND_DELCUSOR; 
	FETCH REMIND_DELCUSOR INTO tmp_deldataids;
	WHILE(tmp_deldataids IS NOT NULL) DO
		DELETE FROM ld_reminds_accepted WHERE FIND_IN_SET(remindsid,tmp_deldataids);
		DELETE FROM ld_crmentity WHERE setype='Reminds' AND FIND_IN_SET(crmid,tmp_deldataids);
		FETCH REMIND_DELCUSOR INTO tmp_deldataids;
	END WHILE;
	CLOSE REMIND_DELCUSOR;

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_remindsdata_transfer
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_remindsdata_transfer`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_remindsdata_transfer`(
)
BEGIN

	DECLARE tmp_dataids MEDIUMTEXT DEFAULT NULL;

	
	DECLARE REMIND_CUSOR CURSOR FOR 
		SELECT
			GROUP_CONCAT(remindsid) AS ids
		FROM (
			SELECT 
				remindsid
			FROM ld_reminds 
			WHERE date_time<DATE_SUB(CURDATE(),INTERVAL 1 MONTH)
				AND (
					status_rmd='已读' 
					OR push_to_yzj=3
					OR push_to_weixin=3 
					OR push_to_ding=3
			)
			LIMIT 1000
		) a;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_dataids = NULL;

	OPEN REMIND_CUSOR; 
	FETCH REMIND_CUSOR INTO tmp_dataids;
	WHILE(tmp_dataids IS NOT NULL) DO
		INSERT INTO ld_reminds_accepted
		SELECT * FROM ld_reminds WHERE FIND_IN_SET(remindsid,tmp_dataids);

		DELETE FROM ld_reminds WHERE FIND_IN_SET(remindsid,tmp_dataids);

		FETCH REMIND_CUSOR INTO tmp_dataids;
	END WHILE;
	CLOSE REMIND_CUSOR;

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_reset_account_nolinkdays
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_reset_account_nolinkdays`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_reset_account_nolinkdays`(
)
BEGIN
	SET @disable_triggers=1;
	UPDATE ld_account SET nolinkdays=DATEDIFF(CURDATE(),DATE_FORMAT(GREATEST(IFNULL(lastcontactdate,'1960-01-01' ),createdtime),'%Y-%m-%d'));
	SET @disable_triggers=NULL;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_reset_expensebudget_byid
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_reset_expensebudget_byid`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_reset_expensebudget_byid`(
	tmp_mybillid TEXT
)
BEGIN

	DECLARE tmp_budgettype VARCHAR(100) DEFAULT '';
	DECLARE tmp_budgetindicators VARCHAR(100) DEFAULT '';
	
	DECLARE MY_RESETCUSOR CURSOR FOR 
					SELECT
						a.expensebudget_type,
						a.budget_indicators
					FROM ld_expensebudget a
					WHERE FIND_IN_SET(a.expensebudgetid,tmp_mybillid)
						AND a.expensebudget_type IN ('salesGoalBudget','salesAchievementBudget')
					GROUP BY a.expensebudget_type,a.budget_indicators;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_budgettype = NULL;

	OPEN MY_RESETCUSOR; 
	FETCH MY_RESETCUSOR INTO tmp_budgettype,tmp_budgetindicators;
	WHILE(tmp_budgettype IS NOT NULL) DO
		SET @exec_resetbudgetinfo='';
		IF tmp_budgettype ='salesGoalBudget' THEN
			SET @exec_resetbudgetinfo=(
				SELECT
					CONCAT("UPDATE ld_expensebudget a ","\r\n",
						"LEFT JOIN ld_expensebudgetdetail b ON b.id=a.expensebudgetid ","\r\n",
						"SET ","\r\n",
						"	b.reference_amount=","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0),","\r\n",
						"	b.amount=IFNULL(b.budget_rate,0)*0.01*","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0),","\r\n",
						"	b.budget_amount=IFNULL(b.adjustment_amount,0)+IFNULL(b.budget_rate,0)*0.01*","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0)","\r\n",
						"WHERE FIND_IN_SET(a.expensebudgetid,'",tmp_mybillid,"') ","\r\n",
							"	AND a.expensebudget_type='salesGoalBudget' ","\r\n",
							"	AND a.budget_indicators='",tmp_budgetindicators,"'"
						) AS exex_sql
				FROM (
					SELECT 
						`name` AS indicators_type,
						`columns` AS budget_column 
					FROM ld_expensebudget_totalcolumns 
					WHERE type='salesGoalBudget' 
					GROUP BY `name`
				) a
				WHERE a.indicators_type=tmp_budgetindicators
			);
		ELSE
			SET @exec_resetbudgetinfo=(
				SELECT
					CONCAT("UPDATE ld_expensebudget a ","\r\n",
						"LEFT JOIN ld_expensebudgetdetail b ON b.id=a.expensebudgetid ","\r\n",
						"SET ","\r\n",
						"	b.reference_amount=(",total_sql,"),","\r\n",
						"	b.amount=IFNULL(b.budget_rate,0)*0.01*(",total_sql,"),","\r\n",
						"	b.budget_amount=IFNULL(b.adjustment_amount,0)+IFNULL(b.budget_rate,0)*0.01*(",total_sql,")","\r\n",
						"WHERE FIND_IN_SET(a.expensebudgetid,'",tmp_mybillid,"') ","\r\n",
							"	AND a.expensebudget_type='salesAchievementBudget' ","\r\n",
							"	AND a.budget_indicators='",tmp_budgetindicators,"'"
						) AS exex_sql
				FROM (
					SELECT
						indicators_type,
						budget_column,
						modulename,
						GROUP_CONCAT(CONCAT("IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ",(SELECT CONCAT(main_tablename,' LEFT JOIN ',custom_tablename,' ON ',main_tablename,'.',primary_key,'=',custom_tablename,'.',primary_key ) FROM ld_tab WHERE `name`=a.modulename)," WHERE deleted=0 AND (CASE WHEN '",a.approved,"'='yes' THEN approvestatus='已批准' ELSE 1=1 END) AND approvestatus<>'已拒绝' AND smownerid=b.lin_users_id AND ",a.time_condition," BETWEEN a.indicators_start_date AND a.indicators_end_date),0)") SEPARATOR '+') AS total_sql
					FROM (
						SELECT 
							`name` AS indicators_type,
							`columns` AS budget_column,
							modulename,
							CASE
								WHEN EXISTS (SELECT 1 FROM ld_field WHERE tablename=LEFT(time_condition_field,LOCATE('.',time_condition_field)-1) AND columnname=RIGHT(time_condition_field,LENGTH(time_condition_field)-LOCATE('.',time_condition_field)) AND presence<>1) THEN time_condition_field
								ELSE time_condition_default
							END AS time_condition,
							approved
						FROM ld_expensebudget_totalcolumns 
						WHERE type='salesAchievementBudget' 
						GROUP BY `name`,`columns`
					) a
					GROUP BY indicators_type
				) a
				WHERE a.indicators_type=tmp_budgetindicators
			);
		END IF;
		
		IF IFNULL(@exec_resetbudgetinfo,'')<>'' THEN
			SET @disable_triggers=1;
			PREPARE resetbudgetinfostmt FROM @exec_resetbudgetinfo;
			EXECUTE resetbudgetinfostmt;
			DEALLOCATE PREPARE resetbudgetinfostmt;
			SET @disable_triggers=NULL;
		END IF;
		FETCH MY_RESETCUSOR INTO tmp_budgettype,tmp_budgetindicators;
	END WHILE;
	CLOSE MY_RESETCUSOR;
	
	UPDATE ld_expensebudget SET total=(SELECT SUM(budget_amount) FROM ld_expensebudgetdetail WHERE id=ld_expensebudget.expensebudgetid) WHERE FIND_IN_SET(expensebudgetid,tmp_mybillid);

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_reset_nianjianinfo
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_reset_nianjianinfo`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_reset_nianjianinfo`(
)
BEGIN

	DECLARE tmp_userid INT(19) DEFAULT 0;
	
	DECLARE MYCUSOR CURSOR FOR 
		SELECT
			a.id
		FROM ld_users a
		WHERE a.hire_date>'1900-01-01'
			AND DATE_FORMAT(a.hire_date,'%m-%d')=DATE_FORMAT(NOW(),'%m-%d');
	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_userid = NULL;

	OPEN MYCUSOR; 
	FETCH MYCUSOR INTO tmp_userid;

	WHILE(tmp_userid IS NOT NULL) DO
		CALL ldcrm_update_sykq_byuserid(tmp_userid);
		FETCH MYCUSOR INTO tmp_userid;
	END WHILE;
	CLOSE MYCUSOR;

END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_saleskitset_showpercent_default
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_saleskitset_showpercent_default`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_saleskitset_showpercent_default`()
BEGIN

    DECLARE tmp_boardid INT(11) DEFAULT 0;
    DECLARE tmp_stuffid INT(11) DEFAULT 0;
    DECLARE tmp_boardstuffid INT(19) DEFAULT 0;

    DECLARE MYCUSOR CURSOR FOR SELECT boardid,stuffid,boardstuffid from ld_homeboard_plate_stuff WHERE stuffid = 35;

    DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_boardid = NULL;

    SET @settype = 'SalesKit_ShowPercent';

    OPEN MYCUSOR;
        FETCH MYCUSOR INTO tmp_boardid,tmp_stuffid,tmp_boardstuffid;
        WHILE(tmp_boardid IS NOT NULL) DO
            INSERT INTO ld_homeboard_plate_setting(boardid,stuffid,boardstuffid,type,setvalue)
            SELECT tmp_boardid,tmp_stuffid,tmp_boardstuffid,@settype,'yes' FROM DUAL
            WHERE NOT EXISTS (
                    SELECT 1 FROM ld_homeboard_plate_setting WHERE boardid = tmp_boardid AND stuffid = tmp_stuffid AND boardstuffid = tmp_boardstuffid AND type = @settype
                );

            FETCH MYCUSOR INTO tmp_boardid,tmp_stuffid,tmp_boardstuffid;
        END WHILE;
    CLOSE MYCUSOR;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_shujuzidian
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_shujuzidian`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ldcrm_shujuzidian`(
	tmp_modulelabel VARCHAR(100)
)
BEGIN

	SET @my_tabid=(
		SELECT
			GROUP_CONCAT(a.tabid) AS tabids
		FROM ld_tab a
		INNER JOIN ld_tranlabel b ON b.Relateid=a.tabid AND b.trantable='ld_tab'
		WHERE a.`name`=tmp_modulelabel
			OR b.fieldlabel=tmp_modulelabel
		GROUP BY a.tabid
	);

	SELECT
		bill_name AS '表单名称',
		block_name AS '区块名称',
		field_name AS '字段名称',
		filed_type AS '字段类型',
		table_name AS '数据库表名',
		show_name AS '显示名称（CH）'
	FROM (
		(SELECT
			1 AS type_seq,
			c.sequence AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS bill_name,
			CONCAT('单据表头-',e.fieldlabel) AS block_name,
			b.columnname AS field_name,
			s.COLUMN_TYPE AS filed_type,
			b.tablename AS table_name,
			d.fieldlabel AS show_name
		FROM ld_tab a
		LEFT JOIN ld_field b ON a.tabid=b.tabid
		LEFT JOIN ld_blocks c ON c.blockid=b.block
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_field' AND d.Relateid=b.fieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel e ON e.trantable='ld_blocks' AND e.Relateid=c.blockid AND e.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
		UNION ALL
		(SELECT
			2 AS type_seq,
			1000000 AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS '表单名称',
			'单据分录-字段信息' AS '区块名称',
			b.columnname AS '字段名称',
			s.COLUMN_TYPE AS '字段类型',
			b.tablename AS '数据库表名',
			d.fieldlabel AS '显示名称（CH）'
		FROM ld_tab a
		LEFT JOIN ld_producttoolfield b ON a.tabid=b.tabid
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_producttoolfield' AND d.Relateid=b.producttoolfieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
		UNION ALL
		(SELECT
			3 AS type_seq,
			1000001 AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS '表单名称',
			'单据分录-字段信息' AS '区块名称',
			b.columnname AS '字段名称',
			s.COLUMN_TYPE AS '字段类型',
			b.tablename AS '数据库表名',
			d.fieldlabel AS '显示名称（CH）'
		FROM ld_tab a
		LEFT JOIN ld_tabdetailfield b ON a.tabid=b.tabid
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_tabdetailfield' AND d.Relateid=b.tabdetailfieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
	) tmp_zidan
	ORDER BY type_seq,block_seq,field_seq;

END
;;
DELIMITER ;

