-- ----------------------------
-- Procedure structure for update_invoice_receivedamount_byinvoiceid
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_invoice_receivedamount_byinvoiceid`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `update_invoice_receivedamount_byinvoiceid`(
	tmp_invoiceid INT(19)
)
BEGIN

	SET @cnt1=0;
	SELECT
		count(1) INTO @cnt1
	FROM (
		SELECT IFNULL(currency_id,1) AS currency_id FROM ld_invoice WHERE invoiceid=tmp_invoiceid
		UNION
		SELECT IFNULL(currency_id,1) FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0
		UNION
		SELECT 
			IFNULL(a.currency_id,1)
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END)
	) a;

	IF @cnt=1 THEN
		-- 没有多币种
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount) INTO @indir_cashtotal FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0;
		UPDATE ld_invoice SET received_amount=IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0) WHERE invoiceid=tmp_invoiceid;
	ELSE
		-- 有多币种,计算已收时统一转换为人民币计算
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount/IFNULL(a.conversion_rate,1)) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount/IFNULL(conversion_rate,1)) INTO @indir_cashtotal FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0;
		UPDATE ld_invoice SET received_amount=(IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0))*IFNULL(conversion_rate,1) WHERE invoiceid=tmp_invoiceid;
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_purchaseinvoice_receivedamount_bypurchaseinvoiceid
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_purchaseinvoice_receivedamount_bypurchaseinvoiceid`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `update_purchaseinvoice_receivedamount_bypurchaseinvoiceid`(
	tmp_invoiceid INT(19)
)
BEGIN

	SET @cnt1=0;
	SELECT
		count(1) INTO @cnt1
	FROM (
		SELECT IFNULL(currency_id,1) AS currency_id FROM ld_purchaseinvoice WHERE purchaseinvoiceid=tmp_invoiceid
		UNION
		SELECT IFNULL(currency_id,1) FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0
		UNION
		SELECT 
			IFNULL(a.currency_id,1)
		FROM ld_sendcashbill a
		LEFT JOIN ld_sendcashbill2payment b ON a.sendcashbillid=b.sendcashbillid
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=84)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END)
	) a;

	IF @cnt=1 THEN
		-- 没有多币种
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount) INTO @dir_cashtotal
		FROM ld_sendcashbill a
		LEFT JOIN ld_sendcashbill2payment b ON a.sendcashbillid=b.sendcashbillid
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=84)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount) INTO @indir_cashtotal FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0;
		UPDATE ld_purchaseinvoice SET pay_amount=IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0) WHERE purchaseinvoiceid=tmp_invoiceid;
	ELSE
		-- 有多币种,计算已收时统一转换为人民币计算
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount/IFNULL(a.conversion_rate,1)) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount/IFNULL(conversion_rate,1)) INTO @indir_cashtotal FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0;
		UPDATE ld_purchaseinvoice SET pay_amount=(IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0))*IFNULL(conversion_rate,1) WHERE purchaseinvoiceid=tmp_invoiceid;
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_purs_total
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_purs_total`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `update_purs_total`(
	tmp_sendcashbillid INT(19)
)
BEGIN
	
	declare tmp_entitytypeid int default 0;
	declare tmp_entitytype varchar(200) default NULL;
	
	declare cur1 CURSOR FOR SELECT DISTINCT
										entitytypeid,
										entitytype
									FROM (
										select
											b.entitytypeid,
											b.entitytype
										from ld_sendcashbill a 
										LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1 and a.sendcashbillid=tmp_sendcashbillid
										UNION
										select 
												c.Purchaseorder_id,
												'PurchaseOrder' entitytype
										from ld_sendcashbill a 
										LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
										INNER JOIN ld_sendpayment c on c.sendpaymentid=b.entitytypeid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1 and a.sendcashbillid=tmp_sendcashbillid) a
									ORDER BY entitytypeid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_entitytypeid = NULL;
	
	select ifnull(deploy_value,0) into @deploy_value from ld_systems_deploy where deploy_type=84;
	select ifnull(deploy_value,0) into @approve_deploy_value from ld_systems_deploy where deploy_type=134;
	
	OPEN cur1;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	while(tmp_entitytypeid is not null) DO
	
		set @tmp_entitytypeid=0;
		set @tmp_entitytypeid=tmp_entitytypeid;
		
		set @cnt1=0;
		select 
			count( DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_purchaseorder where purchaseorderid=@tmp_entitytypeid
			UNION ALL
				select currency_id from ld_purchaseinvoice where purchaseinvoiceid=@tmp_entitytypeid
			UNION ALL
				select currency_id from ld_stock where stock_id=@tmp_entitytypeid 
			UNION ALL	
				select currency_id from ld_sendpayment where sendpaymentid=@tmp_entitytypeid
			UNION ALL
				select 
					a.currency_id 
				from ld_sendcashbill a
				LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			UNION ALL
				select 
					a.currency_id 
				from ld_sendcashbill a
				LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
				where a.deleted=0 and c.Purchaseorder_id=@tmp_entitytypeid and c.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) c;
					
		-- 如果没有多币种的收款
		IF @cnt1=1 THEN
		      set @purs_total=0.00;
			set @purs_date='0000-00-00';
			set @purs_total2=0.00;
			set @purs_date2='0000-00-00';
			
			select
				sum(h.amount) into @purs_total
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(e.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) as g) as h
				where h.entitytypeid=@tmp_entitytypeid
				group by h.entitytypeid;

			select
				max(a.cashbilldate) into @purs_date
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			group by b.entitytypeid;
			
			-- 计算采购订单已收金额时，需要考虑订单对应的回款计划的收款
			select
				sum(h.amount) into @purs_total2
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(e.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) as g) as h
				LEFT JOIN ld_sendpayment i on h.entitytypeid=i.sendpaymentid
				where i.Purchaseorder_id=@tmp_entitytypeid
				group by i.Purchaseorder_id;

			select
				max(a.cashbilldate) into @purs_date2
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
			where a.deleted=0 and c.Purchaseorder_id=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			group by c.Purchaseorder_id;
			
			IF tmp_entitytype='PurchaseOrder' THEN
				update ld_purchaseorder set pay_amount=round(@purs_total,2)+round(@purs_total2,2),pay_balance=round(total-pay_amount,2),sendcashbilldate=IF(@purs_date>@purs_date2,@purs_date,@purs_date2) where purchaseorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PurchaseInvoice' THEN
				update ld_purchaseinvoice set pay_amount=round(@purs_total,2),pay_balance=round(total-round(@purs_total,2),2),sendcashbilldate=@purs_date where purchaseinvoiceid=@tmp_entitytypeid;			
			ELSEIF tmp_entitytype='Stock' THEN
				update ld_stock set pay_amount=round(@purs_total,2),pay_balance=round(total-round(@purs_total,2),2),sendcashbilldate=@purs_date where stock_id=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='SendPayment' THEN
				update ld_sendpayment set Actualamount=round(@purs_total,2),pay_balance=round(Amount-round(@purs_total,2),2),Actualdate=@purs_date where sendpaymentid=@tmp_entitytypeid;
			END IF;
			
			
		-- 如果有多币种的收款	
		ELSE

				set @purs_total=0.00;
			set @purs_date='0000-00-00';
			set @purs_total2=0.00;
			set @purs_date2='0000-00-00';
			
			select
				sum(h.amount) into @purs_total
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment/e.conversion_rate as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(e.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) as g) as h
				where h.entitytypeid=@tmp_entitytypeid
				group by h.entitytypeid;

			select
				max(a.cashbilldate) into @purs_date
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			group by b.entitytypeid;
			
			-- 计算采购订单已收金额时，需要考虑订单对应的回款计划的收款
			select
				sum(h.amount) into @purs_total2
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment/e.conversion_rate as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(e.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) as g) as h
				LEFT JOIN ld_sendpayment i on h.entitytypeid=i.sendpaymentid
				where i.Purchaseorder_id=@tmp_entitytypeid
				group by i.Purchaseorder_id;

			select
				max(a.cashbilldate) into @purs_date2
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
			where a.deleted=0 and c.purchaseorder_id=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			group by c.Purchaseorder_id;
			
			IF tmp_entitytype='PurchaseOrder' THEN
				update ld_purchaseorder set pay_amount=round(@purs_total*conversion_rate,2)+round(@purs_total2*conversion_rate,2),pay_balance=round(total-pay_amount,2),sendcashbilldate=IF(@purs_date>@purs_date2,@purs_date,@purs_date2) where purchaseorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PurchaseInvoice' THEN
				update ld_purchaseinvoice set pay_amount=round(@purs_total*conversion_rate,2),pay_balance=round(total-round(@purs_total*conversion_rate,2),2),sendcashbilldate=@purs_date where purchaseinvoiceid=@tmp_entitytypeid;			
			ELSEIF tmp_entitytype='Stock' THEN
				update ld_stock set pay_amount=round(@purs_total*conversion_rate,2),pay_balance=round(total-round(@purs_total*conversion_rate,2),2),sendcashbilldate=@purs_date where stock_id=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='SendPayment' THEN
				update ld_sendpayment set Actualamount=round(@purs_total*conversion_rate,2),pay_balance=round(Amount-round(@purs_total*conversion_rate,2),2),Actualdate=@purs_date where sendpaymentid=@tmp_entitytypeid;
			END IF;
		END IF;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	end while;
	close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_purs_total1
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_purs_total1`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `update_purs_total1`(
)
BEGIN
	
	declare tmp_entitytypeid int default 0;
	declare tmp_entitytype varchar(200) default NULL;
	
	declare cur1 CURSOR FOR SELECT DISTINCT
										entitytypeid,
										entitytype
									FROM (
										select
											b.entitytypeid,
											b.entitytype
										from ld_sendcashbill a 
										LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1
										UNION
										select 
												c.Purchaseorder_id,
												'PurchaseOrder' entitytype
										from ld_sendcashbill a 
										LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
										INNER JOIN ld_sendpayment c on c.sendpaymentid=b.entitytypeid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1) a
									ORDER BY entitytypeid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_entitytypeid = NULL;
	
	select ifnull(deploy_value,0) into @deploy_value from ld_systems_deploy where deploy_type=84;
	
	OPEN cur1;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	while(tmp_entitytypeid is not null) DO
	
		set @tmp_entitytypeid=0;
		set @tmp_entitytypeid=tmp_entitytypeid;
		
		set @cnt1=0;
		select 
			count( DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_purchaseorder where purchaseorderid=@tmp_entitytypeid
			UNION ALL
				select currency_id from ld_purchaseinvoice where purchaseinvoiceid=@tmp_entitytypeid
			UNION ALL
				select currency_id from ld_stock where stock_id=@tmp_entitytypeid 
			UNION ALL	
				select currency_id from ld_sendpayment where sendpaymentid=@tmp_entitytypeid
			UNION ALL
				select 
					a.currency_id 
				from ld_sendcashbill a
				LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			UNION ALL
				select 
					a.currency_id 
				from ld_sendcashbill a
				LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
				where a.deleted=0 and c.Purchaseorder_id=@tmp_entitytypeid and c.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
					
		-- 如果没有多币种的收款
		IF @cnt1=1 THEN
		  set @purs_total=0.00;
			set @purs_date='0000-00-00';
			set @purs_total2=0.00;
			set @purs_date2='0000-00-00';
			
			select
				sum(h.amount) into @purs_total
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
				where h.entitytypeid=@tmp_entitytypeid
				group by h.entitytypeid;

			select
				max(a.cashbilldate) into @purs_date
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by b.entitytypeid;
			
			-- 计算采购订单已收金额时，需要考虑订单对应的回款计划的收款
			select
				sum(h.amount) into @purs_total2
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
				LEFT JOIN ld_sendpayment i on h.entitytypeid=i.sendpaymentid
				where i.Purchaseorder_id=@tmp_entitytypeid
				group by i.Purchaseorder_id;

			select
				max(a.cashbilldate) into @purs_date2
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
			where a.deleted=0 and c.purchaseorder_id=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by c.Purchaseorder_id;
			
			IF tmp_entitytype='PurchaseOrder' THEN
				update ld_purchaseorder set pay_amount=round(@purs_total,2)+round(@purs_total2,2),pay_balance=round(total-pay_amount,2),sendcashbilldate=IF(@purs_date>@purs_date2,@purs_date,@purs_date2) where purchaseorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PurchaseInvoice' THEN
				update ld_purchaseinvoice set pay_amount=round(@purs_total,2),pay_balance=round(total-round(@purs_total,2),2),sendcashbilldate=@purs_date where purchaseinvoiceid=@tmp_entitytypeid;			
			ELSEIF tmp_entitytype='Stock' THEN
				update ld_stock set pay_amount=round(@purs_total,2),pay_balance=round(total-round(@purs_total,2),2),sendcashbilldate=@purs_date where stock_id=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='SendPayment' THEN
				update ld_sendpayment set Actualamount=round(@purs_total,2),pay_balance=round(Amount-round(@purs_total,2),2),Actualdate=@purs_date where sendpaymentid=@tmp_entitytypeid;
			END IF;
			
			
		-- 如果有多币种的收款	
		ELSE

            set @purs_total=0.00;
			set @purs_date='0000-00-00';
			set @purs_total2=0.00;
			set @purs_date2='0000-00-00';
			
			select
				sum(h.amount) into @purs_total
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment/e.conversion_rate as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
				where h.entitytypeid=@tmp_entitytypeid
				group by h.entitytypeid;

			select
				max(a.cashbilldate) into @purs_date
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by b.entitytypeid;
			
			-- 计算采购订单已收金额时，需要考虑订单对应的回款计划的收款
			select
				sum(h.amount) into @purs_total2
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment/e.conversion_rate as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
				LEFT JOIN ld_sendpayment i on h.entitytypeid=i.sendpaymentid
				where i.Purchaseorder_id=@tmp_entitytypeid
				group by i.Purchaseorder_id;

			select
				max(a.cashbilldate) into @purs_date2
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
			where a.deleted=0 and c.purchaseorder_id=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by c.Purchaseorder_id;
			
			IF tmp_entitytype='PurchaseOrder' THEN
				update ld_purchaseorder set pay_amount=round(@purs_total*conversion_rate,2)+round(@purs_total2*conversion_rate,2),pay_balance=round(total-pay_amount,2),sendcashbilldate=IF(@purs_date>@purs_date2,@purs_date,@purs_date2) where purchaseorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PurchaseInvoice' THEN
				update ld_purchaseinvoice set pay_amount=round(@purs_total*conversion_rate,2),pay_balance=round(total-round(@purs_total*conversion_rate,2),2),sendcashbilldate=@purs_date where purchaseinvoiceid=@tmp_entitytypeid;			
			ELSEIF tmp_entitytype='Stock' THEN
				update ld_stock set pay_amount=round(@purs_total*conversion_rate,2),pay_balance=round(total-round(@purs_total*conversion_rate,2),2),sendcashbilldate=@purs_date where stock_id=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='SendPayment' THEN
				update ld_sendpayment set Actualamount=round(@purs_total*conversion_rate,2),pay_balance=round(Amount-round(@purs_total*conversion_rate,2),2),Actualdate=@purs_date where sendpaymentid=@tmp_entitytypeid;
			END IF;
		END IF;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	end while;
	close cur1;
end
;;
DELIMITER ;

