						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
					where c.entitytypeid=@tmp_entitytypeid and a.deleted=0 and c.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		ELSEIF tmp_entitytype='PaymentPlan' THEN
			select 
				count(DISTINCT currency_id) into @cnt1 
			from (
				select currency_id from ld_paymentplan where paymentplanid=@tmp_entitytypeid and deleted=0
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		ELSEIF tmp_entitytype='Invoice' THEN
			select 
				count(DISTINCT currency_id) into @cnt1 
			from (
				select currency_id from ld_invoice where invoiceid=@tmp_entitytypeid and deleted=0
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		ELSEIF tmp_entitytype='OutboundOrder' THEN
			select 
				count(DISTINCT currency_id) into @cnt1 
			from (
				select currency_id from ld_outboundorder where out_id=@tmp_entitytypeid and deleted=0
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		END IF;
	
		-- 如果没有多币种的收款
		IF @cnt1=1 THEN
			set @sales_total=0.00;
			set @sales_date='0000-00-00';
			set @sales_total2=0.00;
			set @sales_date2='0000-00-00';
				
			select
				sum(h.amount) into @sales_total
			from (
				select 
					a.cashbillid,
					b.entitytypeid,
					b.amount
				from ld_cashbill a 
				INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID  
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.cashbillid,
						f.entitytypeid,
						e.NoPaymentplan as amount
					from ld_cashbill e
					inner JOIN (select * from (
							select CashBillID,entitytypeid 
								from ld_cashbill2paymentplan 
								order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
							where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
			where h.entitytypeid=@tmp_entitytypeid
			group by h.entitytypeid;

			select
				max(a.cashbilldate) into @sales_date
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid 
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by b.entitytypeid;

			-- 计算合同订单已收金额时，需要考虑合同订单对应的回款计划的收款
			select
				sum(h.amount) into @sales_total2
			from (
				select 
					a.cashbillid,
					b.entitytypeid,
					b.amount
				from ld_cashbill a 
				INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID 
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.cashbillid,
						f.entitytypeid,
						e.NoPaymentplan as amount
					from ld_cashbill e
					inner JOIN (select * from (
							select CashBillID,entitytypeid 
								from ld_cashbill2paymentplan 
								order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
							where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
			LEFT JOIN ld_paymentplan i on h.entitytypeid=i.paymentplanid
			where i.entitytypeid=@tmp_entitytypeid
			group by i.entitytypeid;
							
			select
				max(a.cashbilldate) into @sales_date2
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
			LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
			where a.deleted=0 and c.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by c.entitytypeid;
				

			IF tmp_entitytype='SalesOrder' THEN
				update ld_salesorder set received_amount=round(@sales_total,2)+round(@sales_total2,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where salesorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='ServiceContracts' THEN
				update ld_servicecontracts set received_amount=round(@sales_total,2)+round(@sales_total2,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where servicecontractsid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PaymentPlan' THEN
				update ld_paymentplan set actualamount=round(@sales_total,2),receivable_balance=round(amount-@sales_total,2),actualdate=@sales_date where paymentplanid=@tmp_entitytypeid;
				update ld_paymentplan set paymentstatus='未收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)=0;
				update ld_paymentplan set paymentstatus='部分已收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)>0 and IFNULL(receivable_balance,0)>0;  
			ELSEIF tmp_entitytype='Invoice' THEN
				update ld_invoice set received_amount=round(@sales_total,2),receivable_balance=round(total-@sales_total,2),cashbilldate=@sales_date where invoiceid=@tmp_entitytypeid; 
			ELSEIF tmp_entitytype='OutboundOrder' THEN
				update ld_outboundorder set received_amount=round(@sales_total,2),receivable_balance=round(total-@sales_total,2),cashbilldate=@sales_date where out_id=@tmp_entitytypeid; 
			END IF;
				
		-- 如果有多币种的收款
		ELSE
			set @sales_total=0.00;
			set @sales_date='0000-00-00';
			set @sales_total2=0.00;
			set @sales_date2='0000-00-00';
				
			select
				sum(h.amount) into @sales_total
			from (
				select 
					a.cashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_cashbill a 
				INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.cashbillid,
						f.entitytypeid,
						e.NoPaymentplan/e.conversion_rate as amount
					from ld_cashbill e
					inner JOIN (select * from (
							select CashBillID,entitytypeid 
								from ld_cashbill2paymentplan 
								order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
							where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
			where h.entitytypeid=@tmp_entitytypeid
			group by h.entitytypeid;

			select
				max(a.cashbilldate) into @sales_date
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by b.entitytypeid;
						
			-- 计算合同订单已收金额时，需要考虑合同订单对应的回款计划的收款	
			select
				sum(h.amount) into @sales_total2
			from (
				select 
					a.cashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_cashbill a 
				INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.cashbillid,
						f.entitytypeid,
						e.NoPaymentplan/e.conversion_rate as amount
					from ld_cashbill e
					inner JOIN (select * from (
							select CashBillID,entitytypeid 
								from ld_cashbill2paymentplan 
								order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
							where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
			LEFT JOIN ld_paymentplan i on h.entitytypeid=i.paymentplanid
			where i.entitytypeid=@tmp_entitytypeid
			group by i.entitytypeid;
						
			select
				max(a.cashbilldate) into @sales_date2
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID 
			LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
			where a.deleted=0 and c.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by c.entitytypeid;
				
			IF tmp_entitytype='SalesOrder' THEN
				update ld_salesorder set received_amount=round(@sales_total*conversion_rate,2)+round(@sales_total2*conversion_rate,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where salesorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='ServiceContracts' THEN
				update ld_servicecontracts set received_amount=round(@sales_total*conversion_rate,2)+round(@sales_total2*conversion_rate,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where servicecontractsid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PaymentPlan' THEN	
				update ld_paymentplan set actualamount=round(@sales_total*conversion_rate,2),receivable_balance=round(amount-round(@sales_total*conversion_rate,2),2),actualdate=@sales_date where paymentplanid=@tmp_entitytypeid;
				update ld_paymentplan set paymentstatus='未收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)=0;
				update ld_paymentplan set paymentstatus='部分已收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)>0 and IFNULL(receivable_balance,0)>0;   
			ELSEIF tmp_entitytype='Invoice' THEN	
				update ld_invoice set received_amount=round(@sales_total*conversion_rate,2),receivable_balance=round(total-round(@sales_total*conversion_rate,2),2),cashbilldate=@sales_date where invoiceid=@tmp_entitytypeid; 
			ELSEIF tmp_entitytype='OutboundOrder' THEN	
				update ld_outboundorder set received_amount=round(@sales_total*conversion_rate,2),receivable_balance=round(total-round(@sales_total*conversion_rate,2),2),cashbilldate=@sales_date where out_id=@tmp_entitytypeid;
			END IF;
		End IF;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	end while;
	close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_sales_total2
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_sales_total2`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `update_sales_total2`(
	tmp_entitytypeid int(19),
	tmp_entitytype varchar(100)
)
BEGIN
		
	select ifnull(deploy_value,0) into @deploy_value from ld_systems_deploy where deploy_type=83;
	
	set @tmp_entitytypeid=0;
	set @tmp_entitytypeid=tmp_entitytypeid;
	
	set @cnt1=0;	
	IF tmp_entitytype='SalesOrder' THEN
		select 
			count(DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_salesorder where salesorderid=@tmp_entitytypeid and deleted=0
			UNION ALL
				select 
					a.currency_id 
				from ld_cashbill a
				LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			UNION ALL
				select 
					a.currency_id 
				from ld_cashbill a
				LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
				where c.entitytypeid=@tmp_entitytypeid and a.deleted=0 and c.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
	ELSEIF tmp_entitytype='ServiceContracts' THEN
		select 
			count(DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_servicecontracts where servicecontractsid=@tmp_entitytypeid and deleted=0
			UNION ALL
				select 
					a.currency_id 
				from ld_cashbill a
				LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			UNION ALL
				select 
					a.currency_id 
				from ld_cashbill a
				LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
				where c.entitytypeid=@tmp_entitytypeid and a.deleted=0 and c.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
	ELSEIF tmp_entitytype='PaymentPlan' THEN
		select 
			count(DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_paymentplan where paymentplanid=@tmp_entitytypeid and deleted=0
			UNION ALL
				select 
					a.currency_id 
				from ld_cashbill a
				LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
	ELSEIF tmp_entitytype='Invoice' THEN
		select 
			count(DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_invoice where invoiceid=@tmp_entitytypeid and deleted=0
			UNION ALL
				select 
					a.currency_id 
				from ld_cashbill a
				LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
	ELSEIF tmp_entitytype='OutboundOrder' THEN
		select 
			count(DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_outboundorder where out_id=@tmp_entitytypeid and deleted=0
			UNION ALL
				select 
					a.currency_id 
				from ld_cashbill a
				LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
	END IF;

	-- 如果没有多币种的收款
	IF @cnt1=1 THEN
		set @sales_total=0.00;
		set @sales_date='0000-00-00';
		set @sales_total2=0.00;
		set @sales_date2='0000-00-00';
			
		select
			sum(h.amount) into @sales_total
		from (
			select 
				a.cashbillid,
				b.entitytypeid,
				b.amount
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID  
			where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			UNION ALL
			select * from (
				select 
					e.cashbillid,
					f.entitytypeid,
					e.NoPaymentplan as amount
				from ld_cashbill e
				inner JOIN (select * from (
						select CashBillID,entitytypeid 
							from ld_cashbill2paymentplan 
							order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
						where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
							and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
		where h.entitytypeid=@tmp_entitytypeid
		group by h.entitytypeid;

		select
			max(a.cashbilldate) into @sales_date
		from ld_cashbill a 
		INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
		where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid 
			and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
		group by b.entitytypeid;

		-- 计算合同订单已收金额时，需要考虑合同订单对应的回款计划的收款
		select
			sum(h.amount) into @sales_total2
		from (
			select 
				a.cashbillid,
				b.entitytypeid,
				b.amount
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID 
			where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			UNION ALL
			select * from (
				select 
					e.cashbillid,
					f.entitytypeid,
					e.NoPaymentplan as amount
				from ld_cashbill e
				inner JOIN (select * from (
						select CashBillID,entitytypeid 
							from ld_cashbill2paymentplan 
							order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
						where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
							and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
		LEFT JOIN ld_paymentplan i on h.entitytypeid=i.paymentplanid
		where i.entitytypeid=@tmp_entitytypeid
		group by i.entitytypeid;
						
		select
			max(a.cashbilldate) into @sales_date2
		from ld_cashbill a 
		INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
		LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
		where a.deleted=0 and c.entitytypeid=@tmp_entitytypeid
			and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
		group by c.entitytypeid;
			

		IF tmp_entitytype='SalesOrder' THEN
			update ld_salesorder set received_amount=round(@sales_total,2)+round(@sales_total2,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where salesorderid=@tmp_entitytypeid;
		ELSEIF tmp_entitytype='ServiceContracts' THEN
			update ld_servicecontracts set received_amount=round(@sales_total,2)+round(@sales_total2,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where servicecontractsid=@tmp_entitytypeid;
		ELSEIF tmp_entitytype='PaymentPlan' THEN
			update ld_paymentplan set actualamount=round(@sales_total,2),receivable_balance=round(amount-@sales_total,2),actualdate=@sales_date where paymentplanid=@tmp_entitytypeid;
			update ld_paymentplan set paymentstatus='未收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)=0;
			update ld_paymentplan set paymentstatus='部分已收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)>0 and IFNULL(receivable_balance,0)>0;  
		ELSEIF tmp_entitytype='Invoice' THEN
			update ld_invoice set received_amount=round(@sales_total,2),receivable_balance=round(total-@sales_total,2),cashbilldate=@sales_date where invoiceid=@tmp_entitytypeid; 
		ELSEIF tmp_entitytype='OutboundOrder' THEN
			update ld_outboundorder set received_amount=round(@sales_total,2),receivable_balance=round(total-@sales_total,2),cashbilldate=@sales_date where out_id=@tmp_entitytypeid; 
		END IF;
			
	-- 如果有多币种的收款
	ELSE
		set @sales_total=0.00;
		set @sales_date=NULL;
		set @sales_total2=0.00;
		set @sales_date2=NULL;
			
		select
			sum(h.amount) into @sales_total
		from (
			select 
				a.cashbillid,
				b.entitytypeid,
				b.amount/a.conversion_rate as amount
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
			where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			UNION ALL
			select * from (
				select 
					e.cashbillid,
					f.entitytypeid,
					e.NoPaymentplan/e.conversion_rate as amount
				from ld_cashbill e
				inner JOIN (select * from (
						select CashBillID,entitytypeid 
							from ld_cashbill2paymentplan 
							order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
						where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
							and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
		where h.entitytypeid=@tmp_entitytypeid
		group by h.entitytypeid;

		select
			max(a.cashbilldate) into @sales_date
		from ld_cashbill a 
		INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
		where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
			and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
		group by b.entitytypeid;
					
		-- 计算合同订单已收金额时，需要考虑合同订单对应的回款计划的收款	
		select
			sum(h.amount) into @sales_total2
		from (
			select 
				a.cashbillid,
				b.entitytypeid,
				b.amount/a.conversion_rate as amount
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
			where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			UNION ALL
			select * from (
				select 
					e.cashbillid,
					f.entitytypeid,
					e.NoPaymentplan/e.conversion_rate as amount
				from ld_cashbill e
				inner JOIN (select * from (
						select CashBillID,entitytypeid 
							from ld_cashbill2paymentplan 
							order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
						where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
							and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
		LEFT JOIN ld_paymentplan i on h.entitytypeid=i.paymentplanid
		where i.entitytypeid=@tmp_entitytypeid
		group by i.entitytypeid;
					
		select
			max(a.cashbilldate) into @sales_date2
		from ld_cashbill a 
		INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID 
		LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
		where a.deleted=0 and c.entitytypeid=@tmp_entitytypeid
			and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
		group by c.entitytypeid;
			
		IF tmp_entitytype='SalesOrder' THEN
			update ld_salesorder set received_amount=round(@sales_total*conversion_rate,2)+round(@sales_total2*conversion_rate,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where salesorderid=@tmp_entitytypeid;
		ELSEIF tmp_entitytype='ServiceContracts' THEN
			update ld_servicecontracts set received_amount=round(@sales_total*conversion_rate,2)+round(@sales_total2*conversion_rate,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where servicecontractsid=@tmp_entitytypeid;
		ELSEIF tmp_entitytype='PaymentPlan' THEN	
			update ld_paymentplan set actualamount=round(@sales_total*conversion_rate,2),receivable_balance=round(amount-round(@sales_total*conversion_rate,2),2),actualdate=@sales_date where paymentplanid=@tmp_entitytypeid;
			update ld_paymentplan set paymentstatus='未收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)=0;
			update ld_paymentplan set paymentstatus='部分已收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)>0 and IFNULL(receivable_balance,0)>0;   
		ELSEIF tmp_entitytype='Invoice' THEN	
			update ld_invoice set received_amount=round(@sales_total*conversion_rate,2),receivable_balance=round(total-round(@sales_total*conversion_rate,2),2),cashbilldate=@sales_date where invoiceid=@tmp_entitytypeid; 
		ELSEIF tmp_entitytype='OutboundOrder' THEN	
			update ld_outboundorder set received_amount=round(@sales_total*conversion_rate,2),receivable_balance=round(total-round(@sales_total*conversion_rate,2),2),cashbilldate=@sales_date where out_id=@tmp_entitytypeid;
		END IF;
	End IF;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_sales_total3
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_sales_total3`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `update_sales_total3`(
)
BEGIN
	
	declare tmp_entitytypeid int default 0;
	declare tmp_entitytype varchar(200) default NULL;

	declare cur1 CURSOR FOR SELECT DISTINCT
										entitytypeid,
										entitytype
									FROM (
										select
											b.entitytypeid,
											b.entitytype
										from ld_cashbill a 
										LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1
										UNION
										select 
												c.entitytypeid,
												c.entitytype
										from ld_cashbill a 
										LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
										INNER JOIN ld_paymentplan c on c.paymentplanid=b.entitytypeid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1) a
									where entitytype in ('PaymentPlan','Invoice','OutboundOrder')
									ORDER BY entitytypeid;					
									
	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_entitytypeid = NULL;
	
	select ifnull(deploy_value,0) into @deploy_value from ld_systems_deploy where deploy_type=83;
	
	OPEN cur1;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	while(tmp_entitytypeid is not null) DO
	
		set @tmp_entitytypeid=0;
		set @tmp_entitytypeid=tmp_entitytypeid;
		
		
		set @cnt1=0;	
		IF tmp_entitytype='SalesOrder' THEN
			select 
				count(DISTINCT currency_id) into @cnt1 
			from (
				select currency_id from ld_salesorder where salesorderid=@tmp_entitytypeid and deleted=0
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
					where c.entitytypeid=@tmp_entitytypeid and a.deleted=0 and c.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		ELSEIF tmp_entitytype='ServiceContracts' THEN
			select 
				count(DISTINCT currency_id) into @cnt1 
			from (
				select currency_id from ld_servicecontracts where servicecontractsid=@tmp_entitytypeid and deleted=0
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
					where c.entitytypeid=@tmp_entitytypeid and a.deleted=0 and c.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		ELSEIF tmp_entitytype='PaymentPlan' THEN
			select 
				count(DISTINCT currency_id) into @cnt1 
			from (
				select currency_id from ld_paymentplan where paymentplanid=@tmp_entitytypeid and deleted=0
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		ELSEIF tmp_entitytype='Invoice' THEN
			select 
				count(DISTINCT currency_id) into @cnt1 
			from (
				select currency_id from ld_invoice where invoiceid=@tmp_entitytypeid and deleted=0
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		ELSEIF tmp_entitytype='OutboundOrder' THEN
			select 
				count(DISTINCT currency_id) into @cnt1 
			from (
				select currency_id from ld_outboundorder where out_id=@tmp_entitytypeid and deleted=0
				UNION ALL
					select 
						a.currency_id 
					from ld_cashbill a
					LEFT JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
					where b.entitytypeid=@tmp_entitytypeid and a.deleted=0
						and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
		END IF;
	
		-- 如果没有多币种的收款
		IF @cnt1=1 THEN
			set @sales_total=0.00;
			set @sales_date='0000-00-00';
			set @sales_total2=0.00;
			set @sales_date2='0000-00-00';
				
			select
				sum(h.amount) into @sales_total
			from (
				select 
					a.cashbillid,
					b.entitytypeid,
					b.amount
				from ld_cashbill a 
				INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID  
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.cashbillid,
						f.entitytypeid,
						e.NoPaymentplan as amount
					from ld_cashbill e
					inner JOIN (select * from (
							select CashBillID,entitytypeid 
								from ld_cashbill2paymentplan 
								order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
							where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
			where h.entitytypeid=@tmp_entitytypeid
			group by h.entitytypeid;

			select
				max(a.cashbilldate) into @sales_date
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid 
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by b.entitytypeid;

			-- 计算合同订单已收金额时，需要考虑合同订单对应的回款计划的收款
			select
				sum(h.amount) into @sales_total2
			from (
				select 
					a.cashbillid,
					b.entitytypeid,
					b.amount
				from ld_cashbill a 
				INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID 
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.cashbillid,
						f.entitytypeid,
						e.NoPaymentplan as amount
					from ld_cashbill e
					inner JOIN (select * from (
							select CashBillID,entitytypeid 
								from ld_cashbill2paymentplan 
								order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
							where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
			LEFT JOIN ld_paymentplan i on h.entitytypeid=i.paymentplanid
			where i.entitytypeid=@tmp_entitytypeid
			group by i.entitytypeid;
							
			select
				max(a.cashbilldate) into @sales_date2
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
			LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
			where a.deleted=0 and c.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by c.entitytypeid;
				

			IF tmp_entitytype='SalesOrder' THEN
				update ld_salesorder set received_amount=round(@sales_total,2)+round(@sales_total2,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where salesorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='ServiceContracts' THEN
				update ld_servicecontracts set received_amount=round(@sales_total,2)+round(@sales_total2,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where servicecontractsid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PaymentPlan' THEN
				update ld_paymentplan set actualamount=round(@sales_total,2),receivable_balance=round(amount-@sales_total,2),actualdate=@sales_date where paymentplanid=@tmp_entitytypeid;
				update ld_paymentplan set paymentstatus='未收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)=0;
				update ld_paymentplan set paymentstatus='部分已收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)>0 and IFNULL(receivable_balance,0)>0;  
			ELSEIF tmp_entitytype='Invoice' THEN
				update ld_invoice set received_amount=round(@sales_total,2),receivable_balance=round(total-@sales_total,2),cashbilldate=@sales_date where invoiceid=@tmp_entitytypeid; 
			ELSEIF tmp_entitytype='OutboundOrder' THEN
				update ld_outboundorder set received_amount=round(@sales_total,2),receivable_balance=round(total-@sales_total,2),cashbilldate=@sales_date where out_id=@tmp_entitytypeid; 
			END IF;
				
		-- 如果有多币种的收款
		ELSE
		  set @sales_total=0.00;
			set @sales_date='0000-00-00';
			set @sales_total2=0.00;
			set @sales_date2='0000-00-00';
				
			select
				sum(h.amount) into @sales_total
			from (
				select 
					a.cashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_cashbill a 
				INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.cashbillid,
						f.entitytypeid,
						e.NoPaymentplan/e.conversion_rate as amount
					from ld_cashbill e
					inner JOIN (select * from (
							select CashBillID,entitytypeid 
								from ld_cashbill2paymentplan 
								order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
							where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
			where h.entitytypeid=@tmp_entitytypeid
			group by h.entitytypeid;

			select
				max(a.cashbilldate) into @sales_date
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by b.entitytypeid;
						
			-- 计算合同订单已收金额时，需要考虑合同订单对应的回款计划的收款	
			select
				sum(h.amount) into @sales_total2
			from (
				select 
					a.cashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_cashbill a 
				INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.cashbillid,
						f.entitytypeid,
						e.NoPaymentplan/e.conversion_rate as amount
					from ld_cashbill e
					inner JOIN (select * from (
							select CashBillID,entitytypeid 
								from ld_cashbill2paymentplan 
								order by CashBillID,sequence) t group by CashBillID) f on e.cashbillid=f.CashBillID
							where e.deleted=0 and e.NoPaymentplan<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
			LEFT JOIN ld_paymentplan i on h.entitytypeid=i.paymentplanid
			where i.entitytypeid=@tmp_entitytypeid
			group by i.entitytypeid;
						
			select
				max(a.cashbilldate) into @sales_date2
			from ld_cashbill a 
			INNER JOIN ld_cashbill2paymentplan b on a.cashbillid=b.CashBillID 
			LEFT JOIN ld_paymentplan c on b.entitytypeid=c.paymentplanid
			where a.deleted=0 and c.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by c.entitytypeid;
				
			IF tmp_entitytype='SalesOrder' THEN
				update ld_salesorder set received_amount=round(@sales_total*conversion_rate,2)+round(@sales_total2*conversion_rate,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where salesorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='ServiceContracts' THEN
				update ld_servicecontracts set received_amount=round(@sales_total*conversion_rate,2)+round(@sales_total2*conversion_rate,2),receivable_balance=round(total-received_amount,2),cashbilldate=IF(@sales_date>@sales_date2,@sales_date,@sales_date2) where servicecontractsid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PaymentPlan' THEN	
				update ld_paymentplan set actualamount=round(@sales_total*conversion_rate,2),receivable_balance=round(amount-round(@sales_total*conversion_rate,2),2),actualdate=@sales_date where paymentplanid=@tmp_entitytypeid;
				update ld_paymentplan set paymentstatus='未收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)=0;
				update ld_paymentplan set paymentstatus='部分已收' where paymentplanid=@tmp_entitytypeid and IFNULL(actualamount,0)>0 and IFNULL(receivable_balance,0)>0;
			ELSEIF tmp_entitytype='Invoice' THEN	
				update ld_invoice set received_amount=round(@sales_total*conversion_rate,2),receivable_balance=round(total-round(@sales_total*conversion_rate,2),2),cashbilldate=@sales_date where invoiceid=@tmp_entitytypeid; 
			ELSEIF tmp_entitytype='OutboundOrder' THEN	
				update ld_outboundorder set received_amount=round(@sales_total*conversion_rate,2),receivable_balance=round(total-round(@sales_total*conversion_rate,2),2),cashbilldate=@sales_date where out_id=@tmp_entitytypeid;
			END IF;
		End IF;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	end while;
	close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for up_faq_byid
-- ----------------------------
DROP PROCEDURE IF EXISTS `up_faq_byid`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `up_faq_byid`(
	tmp_questionid text
)
BEGIN

	declare tmp_id int(19);
	declare cur1 CURSOR FOR select id from ld_faq where deleted=0 and FIND_IN_SET(id,tmp_questionid);
	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;
	
	OPEN cur1;
	Fetch cur1 into tmp_id;
	while(tmp_id is not null) DO
			update ld_faq set pinci=(select ifnull(count(1),0) from ld_troubletickets where FIND_IN_SET(tmp_id,questionid)) where id=tmp_id;	
			Fetch cur1 into tmp_id;
	end while;
	close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Function structure for func_account_repeatinfo
-- ----------------------------
DROP FUNCTION IF EXISTS `func_account_repeatinfo`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `func_account_repeatinfo`(in_account TEXT,in_tiptype VARCHAR(10)) RETURNS text CHARSET utf8
BEGIN  

	SET @thishalf_accountname=func_changeToHalfAngle(in_account);

	IF in_tiptype='en' THEN
		SET @this_tips=(
			SELECT
				GROUP_CONCAT(tips SEPARATOR '<br>') AS tips
			FROM (
				SELECT
					CONCAT(
						(SELECT fieldlabel FROM ld_tranlabel WHERE Relateid=(SELECT fieldid FROM ld_field WHERE tabid=6 AND columnname='accountname') AND languagetype='en' AND trantable='ld_field' LIMIT 1),
						'『',
						a.accountname,
						'』 already exists, The ',
						(SELECT fieldlabel FROM ld_tranlabel WHERE Relateid=(SELECT fieldid FROM ld_field WHERE tabid=6 AND columnname='smownerid') AND languagetype='en' AND trantable='ld_field' LIMIT 1),
						'『',
						b.last_name,
						'』'
					) AS tips
				FROM ld_account a
				LEFT JOIN ld_users b ON b.id=a.smownerid  
				WHERE a.deleted=0 
					AND a.accountname_halfangle=@thishalf_accountname
					GROUP BY a.accountname,a.smownerid
			) a
		);
	ELSE
		SET @this_tips=(
			SELECT
				GROUP_CONCAT(tips SEPARATOR '<br>') AS tips
			FROM (
				SELECT
					CONCAT(
						(SELECT fieldlabel FROM ld_tranlabel WHERE Relateid=(SELECT fieldid FROM ld_field WHERE tabid=6 AND columnname='accountname') AND languagetype='zh' AND trantable='ld_field' LIMIT 1),
						'『',
						a.accountname,
						'』已存在，当前',
						(SELECT fieldlabel FROM ld_tranlabel WHERE Relateid=(SELECT fieldid FROM ld_field WHERE tabid=6 AND columnname='smownerid') AND languagetype='zh' AND trantable='ld_field' LIMIT 1),
						'『',
						b.last_name,
						'』'
					) AS tips
				FROM ld_account a
				LEFT JOIN ld_users b ON b.id=a.smownerid  
				WHERE a.deleted=0 
					AND a.accountname_halfangle=@thishalf_accountname
					GROUP BY a.accountname,a.smownerid
			) a
		);
	END IF;

	RETURN(@this_tips);

END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for func_changeToCapitalRMB
-- ----------------------------
DROP FUNCTION IF EXISTS `func_changeToCapitalRMB`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `func_changeToCapitalRMB`(MONEY DECIMAL(14,2)) RETURNS varchar(150) CHARSET utf8
BEGIN
	DECLARE RESULT VARCHAR(100) DEFAULT ''; 	
	DECLARE NUM_ROUND VARCHAR(100); 	
	DECLARE NUM_LEFT VARCHAR(100); 	
	DECLARE NUM_RIGHT VARCHAR(2); 		
	DECLARE STR1 VARCHAR(10); 	
	DECLARE STR2 VARCHAR(16); 	
	DECLARE NUM_PRE INT DEFAULT 1; 					
	DECLARE NUM_CURRENT INT; 					
	DECLARE NUM_COUNT INT DEFAULT 0; 					
	DECLARE NUM1 INT;

	SET NUM_ROUND = CONCAT(MONEY, '');
	SET STR1 = '零壹贰叁肆伍陆柒捌玖'; 
	SET STR2 = '元拾佰仟万拾佰仟亿拾佰仟万拾佰仟';
	SET NUM_LEFT = FLOOR(MONEY);
	SET NUM_RIGHT = SUBSTR(NUM_ROUND, LOCATE('.', NUM_ROUND) + 1);

	IF MONEY IS NULL THEN
		SET RESULT = NULL;
		RETURN RESULT;
	END IF;

	IF LENGTH(NUM_LEFT) >= 8 THEN 
		SET NUM1 = CAST(SUBSTR(NUM_LEFT, -8, 4) AS SIGNED);
	ELSE 
		SET NUM1 = CAST(SUBSTR(NUM_LEFT, -LENGTH(NUM_LEFT), LENGTH(NUM_LEFT) - 4) AS SIGNED);
	END IF;

	IF LENGTH(NUM_LEFT) > 16 THEN 
		SET RESULT = '**********';
		RETURN RESULT;
	END IF;

	IF LENGTH(NUM_RIGHT) = 2 THEN
		IF CAST(SUBSTR(NUM_RIGHT, 1, 1) AS SIGNED) = 0 THEN
			SET RESULT = CONCAT('零', SUBSTR(STR1, CAST(SUBSTR(NUM_RIGHT, 2, 1) AS SIGNED) + 1, 1), '分');
		ELSE
			SET RESULT = CONCAT(SUBSTR(STR1, CAST(SUBSTR(NUM_RIGHT, 1, 1) AS SIGNED) + 1, 1), '角', SUBSTR(STR1, CAST(SUBSTR(NUM_RIGHT, 2, 1) AS SIGNED) + 1, 1), '分');
		END IF;
	ELSE 
		IF LENGTH(NUM_RIGHT) = 1 THEN
			SET RESULT = CONCAT(SUBSTR(STR1, CAST(SUBSTR(NUM_RIGHT, 1, 1) AS SIGNED) + 1, 1), '角整');
		ELSE
			SET RESULT = '整';
		END IF;
	END IF;

	myloop: LOOP
		SET NUM_COUNT = NUM_COUNT + 1; 
		IF LENGTH(NUM_LEFT) - NUM_COUNT + 1 > 0 THEN
			SET NUM_CURRENT = CAST(SUBSTR(NUM_LEFT, LENGTH(NUM_LEFT) - NUM_COUNT + 1, 1) AS SIGNED);
		ELSE
			SET NUM_CURRENT = 0;
		END IF;

		IF NUM_CURRENT > 0 THEN 
			SET RESULT = CONCAT(SUBSTR(STR1, NUM_CURRENT + 1, 1), SUBSTR(STR2, NUM_COUNT, 1), RESULT);
		ELSE
			IF NUM_COUNT = 5 THEN
				IF MOD(NUM_COUNT - 1, 4) = 0 AND NUM1 <> 0 THEN 
					SET RESULT = CONCAT(SUBSTR(STR2, NUM_COUNT, 1), RESULT); 
					SET NUM_PRE = 0;
				END IF;
			ELSE
				IF MOD(NUM_COUNT - 1, 4) = 0 THEN 
					SET RESULT = CONCAT(SUBSTR(STR2, NUM_COUNT, 1), RESULT); 
					SET NUM_PRE = 0; 
				END IF;
			END IF;

			IF NUM_PRE > 0 OR LENGTH(NUM_LEFT) = 1 THEN
				SET RESULT = CONCAT(SUBSTR(STR1, NUM_CURRENT + 1, 1), RESULT);
			END IF;
		END IF;

		SET NUM_PRE = NUM_CURRENT;
		IF NUM_COUNT >= LENGTH(NUM_LEFT) THEN 
			LEAVE myloop;
		END IF;
	END LOOP myloop; 

	IF MONEY < 0 THEN
		SET RESULT = CONCAT('负', RESULT);
	END IF;

	SET RESULT = REPLACE(RESULT, '零零分', '整');
	SET RESULT = REPLACE(RESULT, '零分', '整');
	SET RESULT = REPLACE(RESULT, '元整', '元整');
	RETURN RESULT;
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for func_changeToHalfAngle
-- ----------------------------
DROP FUNCTION IF EXISTS `func_changeToHalfAngle`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `func_changeToHalfAngle`(in_str TEXT) RETURNS text CHARSET utf8
BEGIN  

	DECLARE out_str TEXT;

	-- 标点符号
	SET in_str=REPLACE(in_str,'，',',');
	SET in_str=REPLACE(in_str,'＜','<');

	SET in_str=REPLACE(in_str,'．','.');
	SET in_str=REPLACE(in_str,'＞','>');

	SET in_str=REPLACE(in_str,'／','/');
	SET in_str=REPLACE(in_str,'？','?');

	SET in_str=REPLACE(in_str,'：',':');
	SET in_str=REPLACE(in_str,'；',';');

	SET in_str=REPLACE(in_str,'＇',"'");
	SET in_str=REPLACE(in_str,'＂','"');

	SET in_str=REPLACE(in_str,'［','[');
	SET in_str=REPLACE(in_str,'｛','{');

	SET in_str=REPLACE(in_str,'］',']');
	SET in_str=REPLACE(in_str,'｝','}');

	SET in_str=REPLACE(in_str,'＼','\\');
	SET in_str=REPLACE(in_str,'｜','|');

	SET in_str=REPLACE(in_str,'·','`');
	SET in_str=REPLACE(in_str,'～','~');

	SET in_str=REPLACE(in_str,'！','!');
	SET in_str=REPLACE(in_str,'＠','@');
	SET in_str=REPLACE(in_str,'＃','#');
	SET in_str=REPLACE(in_str,'＄','$');
	SET in_str=REPLACE(in_str,'％','%');
