-- ----------------------------
-- Function structure for func_insting_isnumeral
-- ----------------------------
DROP FUNCTION IF EXISTS `func_insting_isnumeral`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `func_insting_isnumeral`(in_string TEXT) RETURNS varchar(10) CHARSET utf8
BEGIN  

	DECLARE is_numeral VARCHAR(10) DEFAULT 'no';

	IF TRIM(IFNULL(in_string,''))='' THEN
		SET is_numeral='yes';
	ELSE
		-- 空格也不允许
		SET in_string=REPLACE(in_string,' ','@');

		SET in_string=REPLACE(in_string,0,'');
		SET in_string=REPLACE(in_string,1,'');
		SET in_string=REPLACE(in_string,2,'');
		SET in_string=REPLACE(in_string,3,'');
		SET in_string=REPLACE(in_string,4,'');
		SET in_string=REPLACE(in_string,5,'');
		SET in_string=REPLACE(in_string,6,'');
		SET in_string=REPLACE(in_string,7,'');
		SET in_string=REPLACE(in_string,8,'');
		SET in_string=REPLACE(in_string,9,'');

		IF TRIM(in_string)='' THEN
			SET is_numeral='yes';
		ELSE
			SET is_numeral='no';
		END IF;
	END IF;

	RETURN(is_numeral);

END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for func_is_accountexists
-- ----------------------------
DROP FUNCTION IF EXISTS `func_is_accountexists`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `func_is_accountexists`(in_accountname TEXT,in_accountid INT(19)) RETURNS varchar(10) CHARSET utf8
BEGIN  

	SET @thishalf_accountname=func_changeToHalfAngle(in_accountname);

	SET @this_existsinfo=(
		SELECT
			CASE
				WHEN EXISTS (SELECT 1 FROM ld_account WHERE deleted=0 AND accountname_halfangle=@thishalf_accountname
								AND (CASE WHEN in_accountid+0>0 THEN accountid<>in_accountid+0 ELSE 1=1 END)) THEN 'yes'
				ELSE 'no'
			END
	);

	RETURN(@this_existsinfo);

END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for getpinyin
-- ----------------------------
DROP FUNCTION IF EXISTS `getpinyin`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `getpinyin`(NAME VARCHAR(255) CHARSET GBK) RETURNS varchar(255) CHARSET gbk
BEGIN

	DECLARE mycode INT(19); 
	DECLARE tmp_lcode VARCHAR(2) CHARSET GBK; 
	DECLARE lcode INT(19); 
	DECLARE tmp_rcode VARCHAR(2) CHARSET GBK;
	DECLARE rcode INT(19); 
	DECLARE mypy VARCHAR(255) CHARSET GBK DEFAULT ''; 
	DECLARE lp INT(19); 

	
	SET mycode = 0 ;
	SET lp = 1 ;
	SET NAME = HEX(NAME);

	WHILE lp < length(NAME) DO
		SET tmp_lcode = SUBSTRING(NAME,lp,2);
		SET lcode = CAST(ASCII(UNHEX(tmp_lcode)) AS UNSIGNED);
		SET tmp_rcode = SUBSTRING(NAME,lp+2,2);
		SET rcode = CAST(ASCII(UNHEX(tmp_rcode)) AS UNSIGNED);

		IF lcode > 128 THEN
			SET mycode = 65536 - lcode * 256 - rcode ; 
			SELECT
				CONCAT(mypy,pin_yin_) INTO mypy
			FROM base_pinyin
			WHERE code_ >= abs(mycode)
			ORDER BY code_ ASC
			LIMIT 1 ;

			SET lp = lp + 4 ;
		ELSE
			SET mypy = CONCAT(mypy,CHAR(CAST(ASCII(UNHEX(SUBSTRING(NAME, lp, 2))) AS UNSIGNED)));
			SET lp = lp + 2 ;
		END IF ;
	END WHILE; 
	RETURN lower(mypy) ;
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for getPY
-- ----------------------------
DROP FUNCTION IF EXISTS `getPY`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `getPY`(in_string text) RETURNS mediumtext CHARSET utf8
BEGIN
	DECLARE tmp_str text charset gbk DEFAULT '' ;
	DECLARE tmp_len SMALLINT DEFAULT 0; 
	DECLARE tmp_char VARCHAR(2) charset gbk DEFAULT '';
	DECLARE tmp_rs text charset gbk DEFAULT '';
	DECLARE tmp_cc VARCHAR(2) charset gbk DEFAULT '';

	SET tmp_str = in_string;
	SET tmp_len = LENGTH(tmp_str);

	WHILE tmp_len > 0 DO 
		SET tmp_char = LEFT(tmp_str,1); 
		SET tmp_cc = tmp_char;
		IF LENGTH(tmp_char)>1 THEN
			SELECT ELT(INTERVAL(CONV(HEX(tmp_char),16,10),0xB0A1,0xB0C5,0xB2C1,0xB4EE,0xB6EA,0xB7A2,0xB8C1,0xB9FE,0xBBF7,0xBFA6,0xC0AC
			,0xC2E8,0xC4C3,0xC5B6,0xC5BE,0xC6DA,0xC8BB,0xC8F6,0xCBFA,0xCDDA ,0xCEF4,0xD1B9,0xD4D1), 
			'A','B','C','D','E','F','G','H','J','K','L','M','N','O','P','Q','R','S','T','W','X','Y','Z') INTO tmp_cc;
		END IF; 

		
		IF tmp_char='钰' THEN
			-- 特殊汉字的处理
			SET tmp_rs = CONCAT(tmp_rs,'Y');
		ELSE
			SET tmp_rs = CONCAT(tmp_rs,tmp_cc);
		END IF;
		
		SET tmp_str = SUBSTRING(tmp_str,2);
		SET tmp_len = LENGTH(tmp_str);
	END WHILE; 
	RETURN tmp_rs;
END
;;
DELIMITER ;

-- ----------------------------
-- Function structure for ldcrm_digitformat
-- ----------------------------
DROP FUNCTION IF EXISTS `ldcrm_digitformat`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `ldcrm_digitformat`(
	in_num DECIMAL(25,8),
	in_type VARCHAR(100)
) RETURNS mediumtext CHARSET gbk
BEGIN

	SET @digit_length=IFNULL((
		SELECT 
			deploy_value 
		FROM ld_systems_deploy 
		WHERE (
			CASE 
				WHEN in_type='数量' THEN deploy_type=49
				WHEN in_type='单价' THEN deploy_type=93
				WHEN in_type='金额' THEN deploy_type=351
			END)
		),2);

	IF @digit_length=0 THEN
		RETURN(ROUND(in_num,0));

	ELSEIF @digit_length=1 THEN
		RETURN(ROUND(in_num,1));

	ELSEIF @digit_length=2 THEN
		RETURN(ROUND(in_num,2));

	ELSEIF @digit_length=3 THEN
		RETURN(ROUND(in_num,3));

	ELSEIF @digit_length=4 THEN
		RETURN(ROUND(in_num,4));

	ELSEIF @digit_length=5 THEN
		RETURN(ROUND(in_num,5));

	ELSEIF @digit_length=6 THEN
		RETURN(ROUND(in_num,6));

	ELSEIF @digit_length=7 THEN
		RETURN(ROUND(in_num,7));

	ELSEIF @digit_length=8 THEN
		RETURN(ROUND(in_num,8));

	ELSE
		RETURN(ROUND(in_num,2));
	END IF;

end
;;
DELIMITER ;

