DELIMITER ;
DROP TRIGGER IF EXISTS `zhixin_huankuan`;
DELIMITER ;;
CREATE TRIGGER `zhixin_huankuan` AFTER UPDATE ON `ld_customform62` FOR EACH ROW BEGIN

if new.approvestatus <> old.approvestatus and (old.approvestatus = '已批准' or new.approvestatus = '已批准') then

update  ld_customform51 a
inner join  ld_customform51scf b on a.customform51id = b.customform51id
left join (select sum(cf_8060) as have_total from ld_customform62 aa inner join  ld_customform62scf bb on  aa.customform62id = bb.customform62id where aa.deleted = 0 and  aa.customform51_id  = new.customform51_id  and  aa.approvestatus = '已批准') c on  1 = 1
set cf_8096 = ifnull(have_total, 0), cf_8097 = ifnull(cf_7921, 0) - ifnull(have_total, 0)
where a.customform51id = new.customform51_id;


update  ld_customform60 a
inner join  ld_customform60scf b on a.customform60id = b.customform60id
left join (select sum(cf_8060) as have_total from ld_customform62 aa inner join  ld_customform62scf bb on  aa.customform62id = bb.customform62id where aa.deleted = 0 and  aa.customform60_id  = new.customform60_id  and  aa.approvestatus = '已批准') c on  1 = 1
set cf_8104 = ifnull(have_total, 0), cf_8105 = ifnull(cf_8047, 0) - ifnull(have_total, 0)
where a.customform60id = new.customform60_id;

end if;

END
;;
